# Validate that a required command exists on the system
# Arguments:
#   $1 - Command name to check
# Returns:
#   0 if command exists, 1 otherwise
# Side effects:
#   Outputs error message to stderr if command not found
validate_command_exists() {
  local cmd="$1"

  if [[ -z "$cmd" ]]; then
    echo -e "${RED}Error: No command specified for validation${NC}" >&2
    return 1
  fi

  if command -v "$cmd" &> /dev/null; then
    return 0
  else
    echo -e "${RED}Error: Required command '${cmd}' not found in PATH${NC}" >&2
    return 1
  fi
}

# Validate that a file exists and is a regular file
# Arguments:
#   $1 - Path to file to validate
# Returns:
#   0 if file exists and is regular file, 1 otherwise
# Side effects:
#   Outputs error message to stderr if file not found
validate_file_exists() {
  local file="$1"

  if [[ -z "$file" ]]; then
    echo -e "${RED}Error: No file path specified for validation${NC}" >&2
    return 1
  fi

  if [[ -f "$file" ]]; then
    return 0
  elif [[ -e "$file" ]]; then
    echo -e "${RED}Error: Path exists but is not a regular file: ${file}${NC}" >&2
    return 1
  else
    echo -e "${RED}Error: File not found: ${file}${NC}" >&2
    return 1
  fi
}

# Validate that a directory exists
# Arguments:
#   $1 - Path to directory to validate
# Returns:
#   0 if directory exists, 1 otherwise
# Side effects:
#   Outputs error message to stderr if directory not found
validate_directory_exists() {
  local dir="$1"

  if [[ -z "$dir" ]]; then
    echo -e "${RED}Error: No directory path specified for validation${NC}" >&2
    return 1
  fi

  if [[ -d "$dir" ]]; then
    return 0
  elif [[ -e "$dir" ]]; then
    echo -e "${RED}Error: Path exists but is not a directory: ${dir}${NC}" >&2
    return 1
  else
    echo -e "${RED}Error: Directory not found: ${dir}${NC}" >&2
    return 1
  fi
}

# Validate that a variable is set and non-empty
# Arguments:
#   $1 - Variable name to check
#   $2 - (Optional) Description for error message
# Returns:
#   0 if variable is set and non-empty, 1 otherwise
validate_variable_set() {
  local var_name="$1"
  local description="${2:-Variable}"

  if [[ -z "${!var_name+x}" ]]; then
    echo -e "${RED}Error: ${description} (${var_name}) is not set${NC}" >&2
    return 1
  fi

  if [[ -z "${!var_name}" ]]; then
    echo -e "${RED}Error: ${description} (${var_name}) is empty${NC}" >&2
    return 1
  fi

  return 0
}

# Validate that a numeric value is within a specified range
# Arguments:
#   $1 - Value to validate
#   $2 - Minimum value (inclusive)
#   $3 - Maximum value (inclusive)
# Returns:
#   0 if value is in range, 1 otherwise
validate_number_range() {
  local value="$1"
  local min="$2"
  local max="$3"

  if ! [[ "$value" =~ ^[0-9]+$ ]]; then
    echo -e "${RED}Error: Value '${value}' is not a valid number${NC}" >&2
    return 1
  fi

  if [[ "$value" -lt "$min" || "$value" -gt "$max" ]]; then
    echo -e "${RED}Error: Value ${value} is outside valid range [${min}, ${max}]${NC}" >&2
    return 1
  fi

  return 0
}

# Validate that a port number is valid (1-65535)
# Arguments:
#   $1 - Port number to validate
# Returns:
#   0 if port is valid, 1 otherwise
validate_port() {
  local port="$1"
  validate_number_range "$port" 1 65535
}

