# Check if Docker is installed and running
# Returns:
#   0 if Docker is available, 1 otherwise
check_docker() {
  # Check if Docker is installed
  if ! command -v docker &> /dev/null; then
    print_error "Docker is not installed"
    echo "" >&2
    echo "🔧 To install Docker:" >&2

    if [[ "$OSTYPE" == darwin* ]]; then
      echo "   1. Download Docker Desktop for Mac:" >&2
      echo "      https://www.docker.com/products/docker-desktop/" >&2
      echo "" >&2
      echo "   2. Or install via Homebrew:" >&2
      echo "      brew install --cask docker" >&2
      echo "" >&2
      echo "   3. Start Docker Desktop from Applications" >&2
    elif [[ "$OSTYPE" == linux* ]]; then
      echo "   Ubuntu/Debian:" >&2
      echo "      curl -fsSL https://get.docker.com | sh" >&2
      echo "" >&2
      echo "   Or install via package manager:" >&2
      echo "      sudo apt-get install docker.io docker-compose" >&2
    else
      echo "   Visit: https://docs.docker.com/get-docker/" >&2
    fi

    echo "" >&2
    echo "After installation, start Docker and run this script again." >&2
    return 1
  fi

  # Check if Docker daemon is running
  if ! docker info &> /dev/null; then
    print_error "Docker is installed but not running"

    # Try to detect if Docker Desktop is installed but not started
    if [[ "$OSTYPE" == darwin* ]]; then
      if [[ -d "/Applications/Docker.app" ]]; then
        echo "" >&2
        echo "🚀 Start Docker Desktop:" >&2
        echo "   open -a Docker" >&2
        echo "" >&2
        echo "Or launch it from:" >&2
        echo "   Applications → Docker" >&2
      else
        echo "" >&2
        echo "❌ Docker Desktop not found in /Applications/" >&2
        echo "   Please install Docker Desktop first:" >&2
        echo "   https://www.docker.com/products/docker-desktop/" >&2
      fi
    elif [[ "$OSTYPE" == linux* ]]; then
      echo "" >&2
      echo "🚀 Start Docker daemon:" >&2
      echo "   sudo systemctl start docker" >&2
      echo "" >&2
      echo "Or enable it to start on boot:" >&2
      echo "   sudo systemctl enable docker && sudo systemctl start docker" >&2
    fi

    echo "" >&2
    echo "Wait for Docker to fully start, then run this script again." >&2
    return 1
  fi

  return 0
}

# Check if Docker Compose is available
# Returns:
#   0 if Docker Compose is available, 1 otherwise
check_docker_compose() {
  if docker compose version &> /dev/null; then
    log_message "DEBUG" "Using 'docker compose' (plugin version)"
    return 0
  elif command -v docker-compose &> /dev/null; then
    log_message "DEBUG" "Using 'docker-compose' (standalone version)"
    return 0
  else
    print_error "Docker Compose is not installed or not accessible"

    echo "" >&2
    echo "ℹ️  Docker Compose is included with Docker Desktop (recommended)" >&2

    if [[ "$OSTYPE" == darwin* ]]; then
      echo "" >&2
      echo "   If you have Docker Desktop installed, make sure it's running." >&2
      echo "" >&2
      echo "   If Docker Compose is still not available:" >&2
      echo "   1. Open Docker Desktop" >&2
      echo "   2. Go to Settings → Advanced" >&2
      echo "   3. Ensure 'Docker Compose' is enabled" >&2
    elif [[ "$OSTYPE" == linux* ]]; then
      echo "" >&2
      echo "   Install Docker Compose standalone:" >&2
      echo "   sudo curl -L \"https://github.com/docker/compose/releases/latest/download/docker-compose-\$(uname -s)-\$(uname -m)\" -o /usr/local/bin/docker-compose" >&2
      echo "   sudo chmod +x /usr/local/bin/docker-compose" >&2
    fi

    echo "" >&2
    echo "For more information:" >&2
    echo "   https://docs.docker.com/compose/install/" >&2
    return 1
  fi
}

# Check available disk space
# Arguments:
#   $1 - Minimum required space in GB (default: 5)
#   $2 - Path to check (default: current directory)
# Returns:
#   0 if sufficient space, 1 otherwise
check_disk_space() {
  local min_gb="${1:-5}"
  local path="${2:-.}"

  local free_space

  # macOS and Linux have different df commands
  if [[ "$OSTYPE" == darwin* ]]; then
    # macOS: use df -h and parse the output (e.g., "50Gi" or "500Mi" or "24Gi")
    local df_output
    df_output="$(df -h "$path" 2>/dev/null | tail -1 | awk '{print $4}')"

    if [[ -z "$df_output" ]]; then
      print_error "Could not determine disk space"
      return 1
    fi

    # Remove the trailing 'i' (macOS uses Gi, Mi, Ki instead of G, M, K)
    df_output="${df_output%i}"

    # Get the suffix (last character)
    local suffix="${df_output: -1}"
    # Get the numeric value (everything except the suffix)
    local value="${df_output%[KMGTPkmgtp]}"

    # Debug logging (can be removed later)
    if [[ "${LOG_LEVEL:-INFO}" == "DEBUG" ]]; then
      echo "DEBUG: df_output='$df_output', suffix='$suffix', value='$value'" >&2
    fi

    case "$suffix" in
      K|k)
        # Kilobytes - very small, definitely not enough
        free_space=0
        ;;
      M|m)
        # Megabytes to GB
        free_space=$((value / 1024))
        ;;
      G|g)
        # Already in GB - ensure it's an integer
        free_space="${value%.*}"  # Remove decimal if present
        # Ensure free_space is a number
        if ! [[ "$free_space" =~ ^[0-9]+$ ]]; then
          free_space=0
        fi
        ;;
      T|t)
        # Terabytes to GB
        free_space=$((value * 1024))
        ;;
      *)
        # Unknown suffix, try to parse as just the number
        free_space="${df_output%[^0-9.]}"
        ;;
    esac

    # Debug logging
    if [[ "${LOG_LEVEL:-INFO}" == "DEBUG" ]]; then
      echo "DEBUG: After case statement, free_space='$free_space'" >&2
    fi
  else
    # Linux: use df -BG (GNU df supports -B for block size)
    free_space="$(df -BG "$path" 2>/dev/null | tail -1 | awk '{print $4}' | tr -d 'G')"
  fi

  # Debug logging
  if [[ "${LOG_LEVEL:-INFO}" == "DEBUG" ]]; then
    echo "DEBUG: Final check - free_space='$free_space', min_gb='$min_gb'" >&2
  fi

  if [[ -z "$free_space" ]] || ! [[ "$free_space" =~ ^[0-9]+$ ]]; then
    print_error "Could not determine disk space"
    return 1
  fi

  if [[ "$free_space" -lt "$min_gb" ]]; then
    print_error "Insufficient disk space: ${free_space}GB available, ${min_gb}GB required"
    return 1
  fi

  return 0
}

# Check if a port is available (not in use)
# Arguments:
#   $1 - Port number to check
#   $2 - Optional: Protocol (tcp/udp, default: tcp)
# Returns:
#   0 if port is available, 1 if in use
check_port_available() {
  local port="$1"
  local protocol="${2:-tcp}"

  if ! validate_port "$port"; then
    return 1
  fi

  local in_use=false

  if [[ "$OSTYPE" == darwin* ]]; then
    # macOS: use lsof
    if lsof -i "${protocol}" -P -n | grep -q ":${port} "; then
      in_use=true
    fi
  elif [[ "$OSTYPE" == linux* ]]; then
    # Linux: use ss or netstat
    if command -v ss &> /dev/null; then
      if ss -ln"${protocol:0:1}" 2>/dev/null | grep -q ":${port} "; then
        in_use=true
      fi
    elif command -v netstat &> /dev/null; then
      if netstat -ln"${protocol:0:1}" 2>/dev/null | grep -q ":${port} "; then
        in_use=true
      fi
    fi
  fi

  if [[ "$in_use" == "true" ]]; then
    print_error "Port ${port} is already in use"
    return 1
  fi

  return 0
}

# Check if multiple ports are available
# Arguments:
#   $@ - Port numbers to check
# Returns:
#   0 if all ports available, 1 if any are in use
check_ports_available() {
  local all_available=true

  for port in "$@"; do
    if ! check_port_available "$port"; then
      all_available=false
    fi
  done

  if [[ "$all_available" == "false" ]]; then
    return 1
  fi

  return 0
}

# Check system memory
# Arguments:
#   $1 - Minimum required memory in MB (default: 2048)
# Returns:
#   0 if sufficient memory, 1 otherwise
check_memory() {
  local min_mb="${1:-2048}"

  local total_mem=0

  if [[ "$OSTYPE" == darwin* ]]; then
    # macOS
    total_mem="$(sysctl -n hw.memsize)"
    total_mb=$((total_mem / 1024 / 1024))
  elif [[ "$OSTYPE" == linux* ]]; then
    # Linux
    total_mb="$(grep MemTotal /proc/meminfo | awk '{print $2}')"
    total_mb=$((total_mb / 1024))
  fi

  if [[ "$total_mb" -lt "$min_mb" ]]; then
    local min_gb=$((min_mb / 1024))
    local total_gb=$((total_mb / 1024))
    print_warning "Low memory: ${total_gb}GB available, ${min_gb}GB recommended"
    return 1
  fi

  return 0
}

# Check network connectivity
# Arguments:
#   $1 - Host to ping (default: 8.8.8.8)
#   $2 - Timeout in seconds (default: 5)
# Returns:
#   0 if connectivity is available, 1 otherwise
check_network() {
  local host="${1:-8.8.8.8}"
  local timeout="${2:-5}"

  if command -v ping &> /dev/null; then
    if ping -c 1 -W "$timeout" "$host" &> /dev/null; then
      return 0
    fi
  fi

  # Fallback: try curl to a reliable endpoint
  if command -v curl &> /dev/null; then
    if curl -s -m "$timeout" -o /dev/null https://www.google.com; then
      return 0
    fi
  fi

  print_error "Network connectivity check failed"
  return 1
}

# Check DNS resolution
# Arguments:
#   $1 - Domain name to resolve
# Returns:
#   0 if DNS resolution works, 1 otherwise
check_dns() {
  local domain="$1"

  if command -v nslookup &> /dev/null; then
    if nslookup "$domain" &> /dev/null; then
      return 0
    fi
  elif command -v host &> /dev/null; then
    if host "$domain" &> /dev/null; then
      return 0
    fi
  elif command -v dig &> /dev/null; then
    if dig "$domain" &> /dev/null; then
      return 0
    fi
  fi

  print_error "DNS resolution failed for: ${domain}"
  return 1
}

# Validate Docker image name format
# Arguments:
#   $1 - Image name to validate
# Returns:
#   0 if valid format, 1 otherwise
validate_docker_image() {
  local image="$1"

  if [[ -z "$image" ]]; then
    print_error "Image name cannot be empty"
    return 1
  fi

  # Check for spaces
  if [[ "$image" =~ [[:space:]] ]]; then
    print_error "Image name cannot contain spaces"
    return 1
  fi

  # Basic format validation (more complex validation could be added)
  # Allows: registry:port/org/image:tag
  if [[ ! "$image" =~ ^[a-zA-Z0-9._:/-]+$ ]]; then
    print_error "Invalid image name format: ${image}"
    return 1
  fi

  return 0
}

# Validate docker-compose.yml file
# Arguments:
#   $1 - Path to docker-compose file
# Returns:
#   0 if valid, 1 otherwise
validate_docker_compose_file() {
  local compose_file="$1"

  if ! validate_file_exists "$compose_file"; then
    return 1
  fi

  # Try to validate with docker-compose config
  if command -v docker-compose &> /dev/null; then
    if docker-compose -f "$compose_file" config &> /dev/null; then
      return 0
    else
      print_error "Invalid docker-compose file format"
      return 1
    fi
  elif docker compose version &> /dev/null; then
    if docker compose -f "$compose_file" config &> /dev/null; then
      return 0
    else
      print_error "Invalid docker-compose file format"
      return 1
    fi
  fi

  # If we can't validate with docker-compose, at least check it's valid YAML
  if command -v yq &> /dev/null; then
    if yq eval '.' "$compose_file" &> /dev/null; then
      return 0
    else
      print_error "Invalid YAML in docker-compose file"
      return 1
    fi
  fi

  # Can't validate, but file exists
  return 0
}

# Check if Docker image exists locally or in registry
# Arguments:
#   $1 - Image name
#   $2 - Optional: --remote to check registry (requires pull attempt)
# Returns:
#   0 if image exists, 1 otherwise
check_image_exists() {
  local image="$1"
  local check_remote="${2:-}"

  # Check local first
  if docker image inspect "$image" &> /dev/null; then
    return 0
  fi

  # Check remote if requested
  if [[ "$check_remote" == "--remote" ]]; then
    if docker pull "$image" &> /dev/null; then
      return 0
    fi
  fi

  print_error "Image not found: ${image}"
  return 1
}

# Validate environment file (.env)
# Arguments:
#   $1 - Path to .env file
# Returns:
#   0 if valid, 1 otherwise
validate_env_file() {
  local env_file="$1"

  if ! validate_file_exists "$env_file"; then
    return 1
  fi

  # Check for common syntax errors
  local line_num=0
  while IFS= read -r line; do
    line_num=$((line_num + 1))

    # Skip comments and empty lines
    [[ "$line" =~ ^# ]] && continue
    [[ -z "$line" ]] && continue

    # Check for valid KEY=VALUE format
    if [[ ! "$line" =~ ^[A-Za-z_][A-Za-z0-9_]*= ]]; then
      print_error "Invalid syntax at line ${line_num} in ${env_file}"
      return 1
    fi
  done < "$env_file"

  return 0
}

