render_template() {
  local template_file="$1"
  local output_file="$2"
  local var_prefix="${3:-}"

  if ! validate_file_exists "$template_file"; then
    return 1
  fi

  # Create output directory if it doesn't exist
  local output_dir
  output_dir="$(dirname "$output_file")"
  if [[ ! -d "$output_dir" ]]; then
    mkdir -p "$output_dir"
  fi

  # Use envsubst for template rendering
  # First, export all variables with the optional prefix
  local content
  content="$(cat "$template_file")"

  # Replace ${VAR} style variables
  # Handle both ${VAR} and $VAR formats
  if [[ -n "$var_prefix" ]]; then
    # Export variables with prefix for envsubst
    local var
    for var in $(compgen -v); do
      if [[ "$var" == "${var_prefix}"* ]]; then
        export "$var"
      fi
    done
  fi

  # Extract all variable references from the template
  local vars
  vars="$(grep -oE '\$\{[a-zA-Z_][a-zA-Z0-9_]*(:[-=+?]?[^}]*)?\}' "$template_file" 2>/dev/null | sed 's/\${//g' | sed 's/[:}].*//g' | sort -u)"

  # Check if all required variables are set (no default value in template)
  for var in $vars; do
    # Check if this variable has a default value in the template
    # Patterns to skip: ${VAR:-default}, ${VAR:=default}, ${VAR:+alt}, ${VAR:?error}
    if grep -qE "\\$\{${var}[:-=?]" "$template_file" 2>/dev/null; then
      # Has a default value or operator, skip validation
      continue
    fi
    # Plain ${VAR} with no default - check if set
    if [[ -z "${!var+x}" ]]; then
      print_error "Required variable not set: \${$var}"
      echo "  Set it with: export $var=value" >&2
      return 1
    fi
  done

  # Use envsubst to substitute all exported variables
  # First, preprocess the template to convert ${VAR:-default} to ${VAR}
  # so envsubst can substitute the values
  local preprocessed_file
  preprocessed_file="$(mktemp)"
  sed 's/\${\([A-Za-z_][A-Za-z0-9_]*\):-[^}]*}/${\1}/g' "$template_file" > "$preprocessed_file"
  envsubst < "$preprocessed_file" > "$output_file"
  rm -f "$preprocessed_file"

  print_success "Rendered: ${output_file}"
  return 0
}

# ============================================================================
# CONFIGURATION FILE GENERATION
# ============================================================================

# Generate .env file from template for docker-compose
# Arguments:
#   $1 - Output directory
#   $2 - Resource token (from Control Plane)
#   $3 - Gateway name
#   $4 - Gateway ID (resource ID)
#   $5 - Optional: Control Plane API URL
#   $6 - Optional: LLM API key
#   $7 - Optional: Image registry
#   $8 - Optional: Image tag
#   $9 - Optional: Gateway port
# Returns:
#   0 if generation succeeds, 1 otherwise
generate_env_file() {
  local output_dir="$1"
  local resource_token="$2"
  local gateway_name="${3:-openclaw-gateway}"
  local gateway_id="${4:-}"
  local control_plane_url="${5:-$DEFAULT_CONTROL_PLANE_URL}"
  local openrouter_key="${6:-}"
  local registry="${7:-$DEFAULT_REGISTRY}"
  local image_tag="${8:-latest}"
  local gateway_port="${9:-$DEFAULT_GATEWAY_PORT}"
  local log_level="${LOG_LEVEL:-$DEFAULT_LOG_LEVEL}"

  if [[ -z "$gateway_id" ]]; then
    gateway_id="$(generate_uuid)"
  fi

  local template_file="${TEMPLATE_DIR}/.env.template"
  local output_file="${output_dir}/.env"

  if [[ ! -f "$template_file" ]]; then
    # Create default content if template doesn't exist
    cat > "$output_file" <<EOF
# OpenClaw Gateway Environment Configuration
# Generated by ClawFarm deployment tools
# DO NOT check this file into version control

# Docker Configuration
REGISTRY=${registry}
IMAGE_TAG=${image_tag}
GATEWAY_PORT=${gateway_port}

# Gateway Configuration
GATEWAY_NAME=${gateway_name}
GATEWAY_ID=${gateway_id}
LOG_LEVEL=${log_level}

# Control Plane Configuration
CONTROL_PLANE_API_URL=${control_plane_url}
RESOURCE_TOKEN=${resource_token}
EOF
    if [[ -n "$openrouter_key" ]]; then
      cat >> "$output_file" <<EOF
OPENROUTER_API_KEY=${openrouter_key}
EOF
    fi
  else
    # Set environment variables for template rendering
    local REGISTRY="$registry"
    local IMAGE_TAG="$image_tag"
    local GATEWAY_PORT="$gateway_port"
    local GATEWAY_NAME="$gateway_name"
    local GATEWAY_ID="$gateway_id"
    local LOG_LEVEL="$log_level"
    local CONTROL_PLANE_API_URL="$control_plane_url"
    local RESOURCE_TOKEN="$resource_token"
    local OPENROUTER_API_KEY="$openrouter_key"
    export REGISTRY IMAGE_TAG GATEWAY_PORT GATEWAY_NAME GATEWAY_ID LOG_LEVEL CONTROL_PLANE_API_URL RESOURCE_TOKEN OPENROUTER_API_KEY
    render_template "$template_file" "$output_file"
  fi

  # Set restrictive permissions
  chmod 600 "$output_file"

  print_success "Generated .env file: ${output_file}"
  return 0
}

# Generate docker-compose.yml file with .env file references
# Arguments:
#   $1 - Output directory
#   $2 - Optional: Image registry (default: DEFAULT_REGISTRY)
#   $3 - Optional: Image tag (default: latest)
#   $4 - Optional: Gateway port (default: DEFAULT_GATEWAY_PORT)
# Returns:
#   0 if generation succeeds, 1 otherwise
generate_compose_file() {
  local output_dir="$1"
  local registry="${2:-$DEFAULT_REGISTRY}"
  local image_tag="${3:-latest}"
  local gateway_port="${4:-$DEFAULT_GATEWAY_PORT}"

  local template_file="${TEMPLATE_DIR}/docker-compose.yml.template"
  local output_file="${output_dir}/docker-compose.yml"

  # Create docker-compose.yml that references .env file
  if [[ ! -f "$template_file" ]]; then
    # Create default content if template doesn't exist
    cat > "$output_file" <<'EOF'
version: '3.8'

services:
  openclaw-gateway:
    image: ${REGISTRY:-clawfarmacrproduction.azurecr.io}/openclaw-gateway${IMAGE_TAG_SEPARATOR:-}${IMAGE_TAG:-latest}
    container_name: ${GATEWAY_NAME:-openclaw-gateway}
    # Extra hosts needed for CDP access to host
    extra_hosts:
      - "host.docker.internal:host-gateway"
    ports:
      - "${GATEWAY_PORT:-18789}:18789"
    env_file:
      - .env
    volumes:
      - openclaw-workspace:/workspace
      - openclaw-logs:/logs
      - ./.openclaw:/home/openclaw/.openclaw
      - ./logs:/var/log/openclaw
    restart: unless-stopped
    healthcheck:
      test: ["CMD", "curl", "-f", "http://localhost:18789/health"]
      interval: 30s
      timeout: 10s
      retries: 3
      start_period: 40s
    networks:
      - openclaw-network

  # Nginx CDP Proxy for Chrome DevTools Protocol
  clawfarm-browser-proxy:
    image: nginx:alpine
    container_name: clawfarm-browser-proxy
    ports:
      - "9223:9223"
    volumes:
      - ./nginx.conf:/etc/nginx/nginx.conf:ro
    extra_hosts:
      - "host.docker.internal:host-gateway"
    restart: unless-stopped
    healthcheck:
      test: ["CMD", "wget", "--quiet", "--tries=1", "--spider", "http://localhost:9223/health"]
      interval: 10s
      timeout: 5s
      retries: 3
      start_period: 5s
    networks:
      - openclaw-network

volumes:
  openclaw-workspace:
    driver: local
  openclaw-logs:
    driver: local

networks:
  openclaw-network:
    driver: bridge
EOF
  else
    # Use template file but don't do envsubst - keep variable references
    cp "$template_file" "$output_file"
  fi

  chmod 644 "$output_file"

  # Copy nginx.conf for browser proxy
  local nginx_conf_source="${PROJECT_ROOT}/docker/browser-proxy/nginx.conf"
  local nginx_conf_dest="${output_dir}/nginx.conf"

  if [[ -f "$nginx_conf_source" ]]; then
    cp "$nginx_conf_source" "$nginx_conf_dest"
    chmod 644 "$nginx_conf_dest"
    print_success "Generated nginx.conf: ${nginx_conf_dest}"
  else
    print_warning "nginx.conf not found at ${nginx_conf_source}"
  fi

  print_success "Generated docker-compose.yml: ${output_file}"
  return 0
}

# Generate openclaw.json configuration file
# Arguments:
#   $1 - Output directory (usually workspace directory)
#   $2 - Optional: Control Plane API URL
# Returns:
#   0 if generation succeeds, 1 otherwise
generate_openclaw_config() {
  local output_dir="$1"
  local control_plane_url="${2:-$DEFAULT_CONTROL_PLANE_URL}"

  local template_file="${TEMPLATE_DIR}/openclaw.json.template"
  local output_file="${output_dir}/openclaw.json"

  # Set environment variables for template rendering
  local CONTROL_PLANE_API_URL="$control_plane_url"
  export CONTROL_PLANE_API_URL

  if [[ ! -f "$template_file" ]]; then
    # Create default content if template doesn't exist
    cat > "$output_file" <<EOF
{
  "version": "1.0.0",
  "control_plane": {
    "api_url": "${control_plane_url}",
    "registration_endpoint": "${control_plane_url}/resources/register",
    "config_endpoint": "${control_plane_url}/resources/\${GATEWAY_ID}/config",
    "events_endpoint": "${control_plane_url}/resources/\${GATEWAY_ID}/events"
  },
  "gateway": {
    "name": "\${GATEWAY_NAME}",
    "id": "\${GATEWAY_ID}",
    "health_check_interval": 30,
    "heartbeat_interval": 60,
    "event_batch_size": 100,
    "event_flush_interval": 30,
    "controlUi": {
      "allowedOrigins": [
        "http://localhost:\${GATEWAY_PORT}",
        "http://127.0.0.1:\${GATEWAY_PORT}",
        "http://localhost:18789",
        "http://127.0.0.1:18789"
      ]
    }
  },
  "features": {
    "offline_mode": true,
    "local_cache_ttl": 3600,
    "enable_event_persistence": true
  }
}
EOF
  else
    render_template "$template_file" "$output_file"
  fi

  chmod 644 "$output_file"

  print_success "Generated openclaw.json: ${output_file}"
  return 0
}

# Generate OpenClaw gateway state configuration
# This creates the configuration file that OpenClaw gateway actually uses
# Arguments:
#   $1 - Deployment directory
#   $2 - Gateway port (default: 18789 — aligned with OpenClaw CLI default;
#        see docs/specs/gateway-per-agency-port-mismatch-2026-06-17.md)
#   $3 - Default LLM model (default: qwen/qwen-2.5-plus)
# Returns:
#   0 if generation succeeds, 1 otherwise
generate_openclaw_state_config() {
  local deploy_dir="$1"
  local gateway_port="${2:-18789}"
  local default_llm_model="${3:-moonshotai/kimi-k2.5}"

  # Create OpenClaw state directory on host
  local openclaw_state_dir="${deploy_dir}/.openclaw"
  if [[ ! -d "$openclaw_state_dir" ]]; then
    mkdir -p "$openclaw_state_dir" || {
      echo "Error: Failed to create OpenClaw state directory: $openclaw_state_dir" >&2
      return 1
    }
  fi

  local openclaw_config_file="${openclaw_state_dir}/openclaw.json"

  # Generate OpenClaw gateway configuration with correct port and agent model
  cat > "$openclaw_config_file" <<EOF
{
  "gateway": {
    "port": ${gateway_port},
    "bind": "lan",
    "auth": {
      "mode": "token",
      "token": "$(generate_password 32)"
    },
    "controlUi": {
      "allowedOrigins": [
        "http://localhost:${gateway_port}",
        "http://127.0.0.1:${gateway_port}",
        "http://localhost:18789",
        "http://127.0.0.1:18789"
      ]
    }
  },
  "agents": {
    "list": [
      {
        "id": "main",
        "model": "openrouter/${default_llm_model}"
      }
    ]
  },
  "plugins": {
    "entries": {
      "openrouter": {
        "enabled": true
      },
      "browser": {
        "enabled": false
      }
    }
  }
}
EOF

  chmod 644 "$openclaw_config_file"

  echo "✓ Generated OpenClaw gateway config: ${openclaw_config_file}"
  return 0
}

# ============================================================================
# INTERACTIVE CONFIGURATION
# ============================================================================

# Prompt user for configuration values
# Arguments:
#   $1 - Prompt type (local|cloud|production)
# Outputs:
#   Configuration values as key=value pairs
prompt_user_config() {
  local prompt_type="$1"
  local config_values=()

  echo "=== OpenClaw Gateway Configuration ==="
  echo "Deployment type: ${prompt_type}"
  echo ""

  # Control Plane API URL
  local control_plane_url
  read -rp "Control Plane API URL [${DEFAULT_CONTROL_PLANE_URL}]: " control_plane_url
  control_plane_url="${control_plane_url:-$DEFAULT_CONTROL_PLANE_URL}"
  config_values+=("CONTROL_PLANE_API_URL=$control_plane_url")

  # Resource Token
  local resource_token
  read -rp "Resource Token (from Control Plane): " resource_token
  while [[ -z "$resource_token" ]]; do
    print_error "Resource Token is required"
    read -rp "Resource Token: " resource_token
  done
  config_values+=("RESOURCE_TOKEN=$resource_token")

  # Gateway Name
  local gateway_name
  local default_name="openclaw-$(hostname -s 2>/dev/null || echo gateway)"
  read -rp "Gateway Name [${default_name}]: " gateway_name
  gateway_name="${gateway_name:-$default_name}"
  config_values+=("GATEWAY_NAME=$gateway_name")

  # Gateway Port
  local gateway_port
  read -rp "Gateway Port [${DEFAULT_GATEWAY_PORT}]: " gateway_port
  gateway_port="${gateway_port:-$DEFAULT_GATEWAY_PORT}"
  while ! validate_port "$gateway_port" 2>/dev/null; do
    print_error "Invalid port number (1-65535)"
    read -rp "Gateway Port: " gateway_port
  done
  config_values+=("GATEWAY_PORT=$gateway_port")

  # Log Level
  local log_level
  read -rp "Log Level [info]: " log_level
  log_level="${log_level:-info}"
  config_values+=("LOG_LEVEL=$log_level")

  # Cloud-specific prompts
  if [[ "$prompt_type" == "cloud" || "$prompt_type" == "production" ]]; then
    # Registry URL
    local registry_url
    read -rp "Container Registry [${DEFAULT_REGISTRY}]: " registry_url
    registry_url="${registry_url:-$DEFAULT_REGISTRY}"
    config_values+=("REGISTRY_URL=$registry_url")

    # Image Tag
    local image_tag
    read -rp "Image Tag [latest]: " image_tag
    image_tag="${image_tag:-latest}"
    config_values+=("IMAGE_TAG=$image_tag")
  fi

  # Output configuration
  for config in "${config_values[@]}"; do
    echo "$config"
  done
}

# Load configuration from file
# Arguments:
#   $1 - Configuration file path (.env or similar)
# Returns:
#   0 if load succeeds, 1 otherwise
load_config_file() {
  local config_file="$1"

  if ! validate_file_exists "$config_file"; then
    return 1
  fi

  # Source the configuration file
  set -o allexport
  # shellcheck source=/dev/null
  source "$config_file"
  set +o allexport

  return 0
}

# ============================================================================
# UTILITY FUNCTIONS
# ============================================================================

# Generate a UUID v4
# Outputs:
#   UUID string
generate_uuid() {
  if [[ "$OSTYPE" == darwin* ]]; then
    uuidgen | tr '[:upper:]' '[:lower:]'
  else
    cat /proc/sys/kernel/random/uuid 2>/dev/null || \
    date +%s%N | md5sum | head -c 32 | tr -d '\n' | \
    sed 's/\([0-9a-f]\{8\}\)\([0-9a-f]\{4\}\)\([0-9a-f]\{4\}\)\([0-9a-f]\{4\}\)\([0-9a-f]\{12\}\)/\1-\2-\3-\4-\5/'
  fi
}

# Generate a secure random password
# Arguments:
#   $1 - Length in bytes (default: 32)
# Outputs:
#   Base64-encoded random string
generate_password() {
  local length="${1:-32}"

  if command -v openssl &> /dev/null; then
    openssl rand -base64 "$length" | tr -d '=+/' | cut -c1-"$length"
  else
    # Fallback to /dev/urandom
    if [[ -f /dev/urandom ]]; then
      tr -dc 'A-Za-z0-9' < /dev/urandom | head -c "$length"
    else
      # Last resort
      date +%s | md5sum | head -c "$length"
    fi
  fi
}

# Validate configuration values
# Arguments:
#   $1 - Configuration file path
# Returns:
#   0 if valid, 1 otherwise
validate_config() {
  local config_file="$1"

  if ! validate_file_exists "$config_file"; then
    return 1
  fi

  # Check for required variables
  local required_vars=("CONTROL_PLANE_API_URL" "RESOURCE_TOKEN")
  local missing_vars=()

  for var in "${required_vars[@]}"; do
    if ! grep -q "^${var}=" "$config_file"; then
      missing_vars+=("$var")
    fi
  done

  if [[ ${#missing_vars[@]} -gt 0 ]]; then
    print_error "Missing required variables: ${missing_vars[*]}"
    return 1
  fi

  return 0
}

# Export functions for use in subshells
export -f render_template
export -f generate_env_file
export -f generate_compose_file
export -f generate_openclaw_config
export -f generate_openclaw_state_config
export -f prompt_user_config
export -f load_config_file
export -f generate_uuid
export -f generate_password
export -f validate_config
