# ---------------------------------------------------------------------------
# state.sh - Deployment state management library
# Part of ClawFarm Deployment Tools Phase 4


# Source dependencies
# shellcheck source=validation.sh

# State file version
STATE_VERSION="1.0.0"

# State directory (default: /var/lib/openclaw)
STATE_DIR="${STATE_DIR:-/var/lib/openclaw}"
STATE_FILE="${STATE_FILE:-${STATE_DIR}/deployment/state.json}"

# Default TTL for checkpoints (24 hours)
CHECKPOINT_TTL="${CHECKPOINT_TTL:-86400}"

# Valid deployment statuses
VALID_STATUSES="in_progress|completed|failed|rolled_back"

# Valid deployment types
VALID_DEPLOYMENT_TYPES="local|cloud"

# ============================================================================
# STATE FILE STRUCTURE
# ============================================================================
#
# {
#   "version": "1.0.0",
#   "deployment_type": "local|cloud",
#   "deployment_id": "uuid-v4",
#   "timestamp": "ISO-8601",
#   "status": "in_progress|completed|failed|rolled_back",
#   "current_step": "step_name",
#   "completed_steps": ["step1", "step2"],
#   "resource_id": "uuid",
#   "control_plane_registered": false,
#   "config_hash": "sha256",
#   "checkpoint": {
#     "step": "step_name",
#     "timestamp": "ISO-8601",
#     "data": {}
#   }
# }
#
# ============================================================================

# ============================================================================
# STATE INITIALIZATION
# ============================================================================

# Initialize a new deployment state file
# Arguments:
#   $1 - State file path (optional, defaults to STATE_FILE)
#   $2 - Deployment type: "local" or "cloud" (required)
# Returns:
#   0 if initialization succeeds, 1 otherwise
init_state() {
  local state_file="${1:-$STATE_FILE}"
  local deployment_type="$2"

  # Validate deployment type
  if ! echo "$deployment_type" | grep -qE "^(${VALID_DEPLOYMENT_TYPES})$"; then
    print_error "Invalid deployment type: ${deployment_type}"
    echo "  Must be one of: $(echo "$VALID_DEPLOYMENT_TYPES" | tr '|' ' ')" >&2
    return 1
  fi

  # Check if path exists (file or directory)
  if [[ -e "$state_file" ]]; then
    if [[ -d "$state_file" ]]; then
      print_error "Path exists as directory: ${state_file}"
      return 1
    fi
    if [[ -f "$state_file" ]]; then
      print_error "State file already exists: ${state_file}"
      echo "  Use load_state() to load existing state" >&2
      return 1
    fi
  fi

  # Generate deployment ID (UUID v4)
  local deployment_id
  deployment_id="$(generate_uuid)"

  # Get current timestamp in ISO-8601 format
  local timestamp
  timestamp="$(date -u +"%Y-%m-%dT%H:%M:%SZ")"

  # Create state directory if it doesn't exist
  local state_dir
  state_dir="$(dirname "$state_file")"
  if [[ ! -d "$state_dir" ]]; then
    mkdir -p "$state_dir"
  fi

  # Build initial state JSON
  local state_json
  state_json="$(cat <<EOF
{
  "version": "${STATE_VERSION}",
  "deployment_type": "${deployment_type}",
  "deployment_id": "${deployment_id}",
  "timestamp": "${timestamp}",
  "status": "in_progress",
  "current_step": "init",
  "completed_steps": [],
  "resource_id": "",
  "control_plane_registered": false,
  "config_hash": "",
  "checkpoint": {
    "step": "",
    "timestamp": "",
    "data": {}
  }
}
EOF
)"

  # Save state atomically
  if ! save_state "$state_file" "$state_json"; then
    print_error "Failed to save initial state"
    return 1
  fi

  print_success "Initialized deployment state: ${state_file}"
  return 0
}

# ============================================================================
# STATE FILE I/O
# ============================================================================

# Save state to file atomically
# Arguments:
#   $1 - State file path (optional, defaults to STATE_FILE)
#   $2 - State JSON content
# Returns:
#   0 if save succeeds, 1 otherwise
save_state() {
  local state_file="${1:-$STATE_FILE}"
  local state_json="$2"

  # Validate state JSON
  if ! validate_json "$state_json"; then
    print_error "Invalid state JSON"
    return 1
  fi

  # Create state directory if it doesn't exist
  local state_dir
  state_dir="$(dirname "$state_file")"
  if [[ ! -d "$state_dir" ]]; then
    mkdir -p "$state_dir" || {
      print_error "Failed to create state directory: ${state_dir}"
      return 1
    }
  fi

  # Write to temporary file first (atomic write)
  local temp_file
  temp_file="${state_file}.tmp.$$"

  if ! echo "$state_json" > "$temp_file"; then
    print_error "Failed to write temporary state file"
    rm -f "$temp_file"
    return 1
  fi

  # Set restrictive permissions (600 - owner read/write only)
  chmod 600 "$temp_file" 2>/dev/null || {
    print_error "Failed to set permissions on state file"
    rm -f "$temp_file"
    return 1
  }

  # Atomic rename to final location
  if ! mv "$temp_file" "$state_file"; then
    print_error "Failed to move state file to final location"
    rm -f "$temp_file"
    return 1
  fi

  return 0
}

# Load state from file
# Arguments:
#   $1 - State file path (optional, defaults to STATE_FILE)
# Outputs:
#   State JSON content
# Returns:
#   0 if load succeeds, 1 otherwise
load_state() {
  local state_file="${1:-$STATE_FILE}"

  # Check if file exists
  if [[ ! -f "$state_file" ]]; then
    print_error "State file not found: ${state_file}"
    return 1
  fi

  # Verify file permissions are not too open
  local perms
  perms="$(stat -c %a "$state_file" 2>/dev/null || stat -f %Lp "$state_file" 2>/dev/null)"
  if [[ "$perms" != "600" ]] && [[ ! "$perms" == *"600"* ]]; then
    print_warning "State file has insecure permissions: ${perms}"
    print_warning "Fixing with: chmod 600 ${state_file}"
    chmod 600 "$state_file" 2>/dev/null || true
  fi

  # Read and output state content
  cat "$state_file"
  return 0
}

# ============================================================================
# STATE MODIFICATION
# ============================================================================

# Update deployment status
# Arguments:
#   $1 - State file path (optional, defaults to STATE_FILE)
#   $2 - New status: in_progress, completed, failed, rolled_back
# Returns:
#   0 if update succeeds, 1 otherwise
update_status() {
  local state_file="${1:-$STATE_FILE}"
  local new_status="$2"

  # Validate status
  if ! echo "$new_status" | grep -qE "^(${VALID_STATUSES})$"; then
    print_error "Invalid status: ${new_status}"
    echo "  Must be one of: $(echo "$VALID_STATUSES" | tr '|' ' ')" >&2
    return 1
  fi

  # Check immutability for completed deployments
  if is_immutable "$state_file" 2>/dev/null; then
    local current_status
    current_status="$(jq -r '.status' "$state_file" 2>/dev/null || echo "")"
    if [[ "$current_status" == "completed" ]] && [[ "$new_status" != "rolled_back" ]]; then
      print_error "Cannot modify completed deployment"
      echo "  Use rollback() to revert to previous state" >&2
      return 1
    fi
  fi

  # Load current state
  local state_json
  if ! state_json="$(load_state "$state_file")"; then
    return 1
  fi

  # Get current timestamp
  local timestamp
  timestamp="$(date -u +"%Y-%m-%dT%H:%M:%SZ")"

  # Update status and timestamp
  local updated_state
  updated_state="$(echo "$state_json" | jq \
    --arg status "$new_status" \
    --arg timestamp "$timestamp" \
    '.status = $status | .timestamp = $timestamp')"

  # Save updated state
  save_state "$state_file" "$updated_state"
  print_success "Status updated: ${new_status}"
  return 0
}

# Set current step
# Arguments:
#   $1 - State file path (optional, defaults to STATE_FILE)
#   $2 - Step name
# Returns:
#   0 if update succeeds, 1 otherwise
set_current_step() {
  local state_file="${1:-$STATE_FILE}"
  local step_name="$2"

  # Load current state
  local state_json
  if ! state_json="$(load_state "$state_file")"; then
    return 1
  fi

  # Update current step
  local updated_state
  updated_state="$(echo "$state_json" | jq \
    --arg step "$step_name" \
    '.current_step = $step')"

  # Save updated state
  save_state "$state_file" "$updated_state"
  return 0
}

# Add completed step to completed_steps array
# Arguments:
#   $1 - State file path (optional, defaults to STATE_FILE)
#   $2 - Step name to add
# Returns:
#   0 if addition succeeds, 1 otherwise
add_completed_step() {
  local state_file="${1:-$STATE_FILE}"
  local step_name="$2"

  # Load current state
  local state_json
  if ! state_json="$(load_state "$state_file")"; then
    return 1
  fi

  # Add step if not already present
  local updated_state
  updated_state="$(echo "$state_json" | jq \
    --arg step "$step_name" \
    '.completed_steps |= (. + [$step] | unique)')"

  # Save updated state
  save_state "$state_file" "$updated_state"
  return 0
}

# Check if a step has been completed
# Arguments:
#   $1 - State file path (optional, defaults to STATE_FILE)
#   $2 - Step name to check
# Returns:
#   0 if step is completed, 1 otherwise
is_step_completed() {
  local state_file="${1:-$STATE_FILE}"
  local step_name="$2"

  # Load current state
  local state_json
  if ! state_json="$(load_state "$state_file")"; then
    return 1
  fi

  # Check if step is in completed_steps array
  local found
  found="$(echo "$state_json" | jq \
    --arg step "$step_name" \
    '.completed_steps | index($step)')"

  if [[ "$found" != "null" ]]; then
    return 0
  fi
  return 1
}

# ============================================================================
# CHECKPOINT MANAGEMENT
# ============================================================================

# Add a checkpoint for resume capability
# Arguments:
#   $1 - State file path (optional, defaults to STATE_FILE)
#   $2 - Step name
#   $3 - Checkpoint data (JSON string or object)
# Returns:
#   0 if checkpoint is saved, 1 otherwise
add_checkpoint() {
  local state_file="${1:-$STATE_FILE}"
  local step_name="$2"
  local checkpoint_data="${3:-{}}"

  # Load current state
  local state_json
  if ! state_json="$(load_state "$state_file")"; then
    return 1
  fi

  # Get current timestamp
  local timestamp
  timestamp="$(date -u +"%Y-%m-%dT%H:%M:%SZ")"

  # Trim whitespace from checkpoint_data (including trailing newlines)
  checkpoint_data="$(echo "$checkpoint_data" | jq -c '.')"

  # Update checkpoint using the compact JSON
  local updated_state
  updated_state="$(echo "$state_json" | jq \
    --arg step "$step_name" \
    --arg timestamp "$timestamp" \
    --argjson data "$checkpoint_data" \
    '.checkpoint = {step: $step, timestamp: $timestamp, data: $data}')"

  # Save updated state
  save_state "$state_file" "$updated_state"
  print_success "Checkpoint saved: ${step_name}"
  return 0
}

# Restore from checkpoint
# Arguments:
#   $1 - State file path (optional, defaults to STATE_FILE)
# Outputs:
#   Checkpoint data as JSON
# Returns:
#   0 if restore succeeds, 1 otherwise
restore_checkpoint() {
  local state_file="${1:-$STATE_FILE}"

  # Load current state
  local state_json
  if ! state_json="$(load_state "$state_file")"; then
    return 1
  fi

  # Extract checkpoint
  local checkpoint
  checkpoint="$(echo "$state_json" | jq '.checkpoint')"

  # Check if checkpoint exists
  local step_name
  step_name="$(echo "$checkpoint" | jq -r '.step')"
  if [[ -z "$step_name" ]] || [[ "$step_name" == "null" ]]; then
    print_error "No checkpoint found"
    return 1
  fi

  # Output checkpoint data
  echo "$checkpoint"
  print_success "Restored checkpoint: ${step_name}"
  return 0
}

# Clear checkpoint (after successful resume)
# Arguments:
#   $1 - State file path (optional, defaults to STATE_FILE)
# Returns:
#   0 if clear succeeds, 1 otherwise
clear_checkpoint() {
  local state_file="${1:-$STATE_FILE}"

  # Load current state
  local state_json
  if ! state_json="$(load_state "$state_file")"; then
    return 1
  fi

  # Clear checkpoint
  local updated_state
  updated_state="$(echo "$state_json" | jq \
    '.checkpoint = {step: "", timestamp: "", data: {}}')"

  # Save updated state
  save_state "$state_file" "$updated_state"
  return 0
}

# ============================================================================
# STATE VALIDATION
# ============================================================================

# Validate JSON format
# Arguments:
#   $1 - JSON string to validate
# Returns:
#   0 if valid JSON, 1 otherwise
validate_json() {
  local json_string="$1"

  if [[ -z "$json_string" ]]; then
    return 1
  fi

  # Use jq to validate JSON
  if ! echo "$json_string" | jq . >/dev/null 2>&1; then
    return 1
  fi

  return 0
}

# Verify state file integrity
# Arguments:
#   $1 - State file path (optional, defaults to STATE_FILE)
# Returns:
#   0 if state is valid, 1 otherwise
verify_state_integrity() {
  local state_file="${1:-$STATE_FILE}"

  # Check if file exists
  if [[ ! -f "$state_file" ]]; then
    print_error "State file not found: ${state_file}"
    return 1
  fi

  # Load and validate JSON
  local state_json
  if ! state_json="$(load_state "$state_file")"; then
    return 1
  fi

  # Validate required fields
  local required_fields=("version" "deployment_type" "deployment_id" "timestamp" "status")
  for field in "${required_fields[@]}"; do
    local value
    value="$(echo "$state_json" | jq -r ".$field")"
    if [[ "$value" == "null" ]] || [[ -z "$value" ]]; then
      print_error "Missing required field: ${field}"
      return 1
    fi
  done

  # Validate version
  local version
  version="$(echo "$state_json" | jq -r '.version')"
  if [[ "$version" != "$STATE_VERSION" ]]; then
    print_warning "State file version mismatch: ${version} (expected ${STATE_VERSION})"
  fi

  # Validate status
  local status
  status="$(echo "$state_json" | jq -r '.status')"
  if ! echo "$status" | grep -qE "^(${VALID_STATUSES})$"; then
    print_error "Invalid status: ${status}"
    return 1
  fi

  # Validate deployment_type
  local deployment_type
  deployment_type="$(echo "$state_json" | jq -r '.deployment_type')"
  if ! echo "$deployment_type" | grep -qE "^(${VALID_DEPLOYMENT_TYPES})$"; then
    print_error "Invalid deployment_type: ${deployment_type}"
    return 1
  fi

  return 0
}

# Check if deployment is immutable (completed)
# Arguments:
#   $1 - State file path (optional, defaults to STATE_FILE)
# Outputs:
#   "true" or "false"
# Returns:
#   0 (always succeeds)
is_immutable() {
  local state_file="${1:-$STATE_FILE}"

  # Load current state
  local state_json
  if ! state_json="$(load_state "$state_file")"; then
    echo "false"
    return 0
  fi

  # Check status
  local status
  status="$(echo "$state_json" | jq -r '.status')"

  if [[ "$status" == "completed" ]]; then
    echo "true"
  else
    echo "false"
  fi

  return 0
}

