# Validate deployment environment
# Arguments:
#   $1 - Deployment directory
#   $2 - Deployment type (local|cloud)
# Returns:
#   0 if environment is valid, 1 otherwise
validate_environment() {
  local deploy_dir="$1"
  local deployment_type="$2"

  print_info "Validating deployment environment..."

  # Check deployment directory
  if [[ ! -d "$deploy_dir" ]]; then
    print_error "Deployment directory not found: ${deploy_dir}"
    return 1
  fi

  # Check Docker
  if ! check_docker; then
    return 1
  fi

  # Check Docker Compose
  if ! check_docker_compose; then
    return 1
  fi

  # Validate deployment type
  if ! echo "$deployment_type" | grep -qE "^(local|cloud)$"; then
    print_error "Invalid deployment type: ${deployment_type}"
    return 1
  fi

  # Additional prerequisites
  if ! validate_prerequisites; then
    return 1
  fi

  print_success "Environment validation passed"
  return 0
}

# Validate prerequisites for deployment
# Returns:
#   0 if all prerequisites are met, 1 otherwise
validate_prerequisites() {
  # Check for required commands
  local required_commands=("jq" "curl" "envsubst")
  local missing_commands=()

  for cmd in "${required_commands[@]}"; do
    if ! command -v "$cmd" &> /dev/null; then
      missing_commands+=("$cmd")
    fi
  done

  # If any commands are missing, provide installation guidance
  if [[ ${#missing_commands[@]} -gt 0 ]]; then
    print_error "Missing required commands: ${missing_commands[*]}"
    echo "" >&2
    echo "🔧 To install missing tools:" >&2

    if [[ "$OSTYPE" == darwin* ]]; then
      echo "" >&2
      echo "   Install via Homebrew:" >&2
      echo "   brew install jq" >&2
      echo "" >&2
      echo "   (curl and envsubst are included with macOS)" >&2
    elif [[ "$OSTYPE" == linux* ]]; then
      echo "" >&2
      echo "   Ubuntu/Debian:" >&2
      echo "   sudo apt-get install -y jq curl gettext-base" >&2
      echo "" >&2
      echo "   CentOS/RHEL:" >&2
      echo "   sudo yum install -y jq curl gettext" >&2
    fi

    echo "" >&2
    return 1
  fi

  # Check disk space (minimum 5GB)
  # Use current directory or home for check, not $DEPLOY_DIR (which may not exist yet)
  local check_path="${HOME:-.}"
  if ! check_disk_space 5 "$check_path"; then
    print_warning "Could not verify disk space, continuing anyway"
  fi

  # Check memory (minimum 2GB)
  if ! check_memory 2048; then
    print_warning "Low memory detected. Deployment may fail."
  fi

  return 0
}

