# Get latest image tag from registry
# Arguments:
#   $1 - Image registry URL
# Returns:
#   Latest tag name, or "latest" if detection fails
get_latest_image_tag() {
  local registry="$1"
  local image_name="${registry}/openclaw-gateway"

  local latest_tag=""

  # Method 0 (bundled): BUNDLED_VERSION baked in by bundle-install-sh.sh.
  #   Format: "<openclaw_version>-<resource_plane_version>" (matches VERSION file).
  if [[ -n "${BUNDLED_VERSION:-}" ]]; then
    case "${BUNDLED_VERSION}" in
      *-*)
        local _bundled_oc="${BUNDLED_VERSION%%-*}"
        local _bundled_rp="${BUNDLED_VERSION##*-}"
        if [[ -n "${_bundled_oc}" ]] && [[ -n "${_bundled_rp}" ]]; then
          latest_tag="${_bundled_oc}-${_bundled_rp}"
          print_success "Using bundled version: ${latest_tag}" >&2
          echo "${latest_tag}"
          return 0
        fi
        ;;
    esac
  fi  # Method 1: Use VERSION file if it exists in repo (most reliable)
  if [[ -f "${SCRIPT_DIR}/../../../VERSION" ]]; then
    local version_file="${SCRIPT_DIR}/../../../VERSION"
    if grep -q "OPENCLAW_VERSION=" "$version_file"; then
      local openclaw_version=$(grep "OPENCLAW_VERSION=" "$version_file" | cut -d'=' -f2)
      local resource_plane_version=$(grep "RESOURCE_PLANE_VERSION=" "$version_file" | cut -d'=' -f2)
      if [[ -n "$openclaw_version" ]] && [[ -n "$resource_plane_version" ]]; then
        latest_tag="${openclaw_version}-${resource_plane_version}"
        print_success "Found version in VERSION file: ${latest_tag}" >&2
        echo "$latest_tag"
        return 0
      fi
    fi
  fi

  # Method 2: Try docker manifest to check common version patterns
  if [[ -z "$latest_tag" ]] && command -v docker &> /dev/null; then
    local current_year=$(date +%Y)
    local current_month=$(date +%Y%m | cut -c5-6)

    # Try recent monthly versions (last 6 months)
    for i in {0..5}; do
      local month_offset=$((current_month - i))
      local year=$current_year
      if [[ $month_offset -le 0 ]]; then
        month_offset=$((month_offset + 12))
        year=$((current_year - 1))
      fi
      # Pad month with zero if needed
      local test_month=$(printf "%02d" $month_offset)
      local test_tag="${year}.${test_month}.10"

      # Test if this tag exists by trying to pull manifest
      if docker manifest inspect "${image_name}:${test_tag}" &>/dev/null; then
        latest_tag="$test_tag"
        print_success "Found valid tag: ${latest_tag}" >&2
        break
      fi
    done
  fi

  if [[ -n "$latest_tag" ]]; then
    echo "$latest_tag"
  else
    print_warning "Could not detect latest tag, will use 'latest'" >&2
    echo "latest"
  fi
}

# Pull required Docker images
# Arguments:
#   $1 - Deployment directory
#   $2 - Registry (optional)
#   $3 - Image tag (optional, auto-detected if not specified)
# Returns:
#   0 if pull succeeds, 1 otherwise
pull_images() {
  local deploy_dir="$1"
  local registry="${2:-${REGISTRY:-}}"
  local tag="${3:-${IMAGE_TAG:-}}"

  # Auto-detect latest tag if not specified
  if [[ -z "$tag" ]]; then
    print_info "Auto-detecting latest image version..."
    tag=$(get_latest_image_tag "$registry")
    print_info "Using detected version: ${tag}"
  fi

  print_info "Pulling Docker images using docker-compose..."

  local compose_file="${deploy_dir}/docker-compose.yml"

  if [[ ! -f "$compose_file" ]]; then
    print_error "docker-compose.yml not found in ${deploy_dir}"
    return 1
  fi

  # Change to deployment directory for docker-compose to find .env file
  local original_dir="$(pwd)"
  cd "$deploy_dir" || {
    print_error "Failed to change to deployment directory: ${deploy_dir}"
    return 1
  }

  # Use docker-compose to pull images - this properly handles variable expansion from .env
  if ! docker-compose pull 2>&1; then
    print_error "Failed to pull images using docker-compose"
    cd "$original_dir"
    return 1
  fi

  cd "$original_dir"

  print_success "Images pulled successfully"
  return 0
}

