# Start containers using docker-compose
# Arguments:
#   $1 - Deployment directory
# Returns:
#   0 if start succeeds, 1 otherwise
start_containers() {
  local deploy_dir="$1"
  local compose_file="${deploy_dir}/docker-compose.yml"

  print_info "Starting containers..."

  # Skip file check in test mode (when DOCKER_COMPOSE_CMD is set)
  if [[ -z "${DOCKER_COMPOSE_CMD:-}" ]]; then
    if [[ ! -f "$compose_file" ]]; then
      print_error "docker-compose.yml not found: ${compose_file}"
      return 1
    fi
  fi

  cd "$deploy_dir" || return 1

  # Determine which docker compose command to use
  # Check for DOCKER_COMPOSE_CMD environment variable first (for testing)
  local compose_cmd
  if [[ -n "${DOCKER_COMPOSE_CMD:-}" ]]; then
    compose_cmd="$DOCKER_COMPOSE_CMD"
  elif type docker-compose &> /dev/null; then
    compose_cmd="docker-compose"
  elif docker compose version &> /dev/null; then
    compose_cmd="docker compose"
  else
    print_error "Docker Compose not available"
    return 1
  fi

  # Start containers in detached mode
  if ! $compose_cmd up -d; then
    print_error "Failed to start containers"
    return 1
  fi

  print_success "Containers started"
  return 0
}

# Stop running containers
# Arguments:
#   $1 - Deployment directory
# Returns:
#   0 if stop succeeds, 1 otherwise
stop_containers() {
  local deploy_dir="$1"
  local compose_file="${deploy_dir}/docker-compose.yml"

  print_info "Stopping containers..."

  if [[ ! -f "$compose_file" ]]; then
    print_warning "docker-compose.yml not found, nothing to stop"
    return 0
  fi

  cd "$deploy_dir" || return 1

  # Determine which docker compose command to use
  # Check for DOCKER_COMPOSE_CMD environment variable first (for testing)
  local compose_cmd
  if [[ -n "${DOCKER_COMPOSE_CMD:-}" ]]; then
    compose_cmd="$DOCKER_COMPOSE_CMD"
  elif type docker-compose &> /dev/null; then
    compose_cmd="docker-compose"
  elif docker compose version &> /dev/null; then
    compose_cmd="docker compose"
  else
    print_error "Docker Compose not available"
    return 1
  fi

  # Stop containers
  if ! $compose_cmd down; then
    print_error "Failed to stop containers"
    return 1
  fi

  print_success "Containers stopped"
  return 0
}

