# services.sh - System service installation and management
# Handles launchd (macOS) and systemd (Linux) services


# Source dependencies
# shellcheck source=validation.sh

# Colors for output
if [ -t 1 ]; then
  BLUE='\033[0;34m'
  GREEN='\033[0;32m'
  NC='\033[0m'
else
  BLUE=''
  GREEN=''
  NC=''
fi

# ============================================================================
# SERVICE INSTALLATION (macOS - launchd)
# ============================================================================

# Install launchd service for macOS
# Arguments:
#   $1 - Service name (e.g., com.clawfarm.gateway)
#   $2 - Plist file path (template)
#   $3 - Deploy directory
#   $4 - Log directory
# Returns:
#   0 on success, 1 on failure
install_launchd_service() {
  local service_name="$1"
  local plist_template="$2"
  local deploy_dir="$3"
  local log_dir="$4"

  print_info "Installing launchd service: ${service_name}"

  # Create launchd directory
  local launchd_dir="$HOME/Library/LaunchAgents"
  if [[ ! -d "$launchd_dir" ]]; then
    mkdir -p "$launchd_dir" || {
      print_error "Failed to create LaunchAgents directory"
      return 1
    }
  fi

  # Generate plist file with substituted variables
  local plist_file="${launchd_dir}/${service_name}.plist"

  # Substitute variables in template
  sed -e "s|\${DEPLOY_DIR}|${deploy_dir}|g" \
      -e "s|\${LOG_DIR}|${log_dir}|g" \
      -e "s|\${USER}|${USER}|g" \
      "$plist_template" > "$plist_file"

  # Load the service
  if launchctl list | grep -q "$service_name"; then
    print_info "Service already loaded, unloading first..."
    launchctl unload "$plist_file" 2>/dev/null || true
  fi

  # Load and start the service
  launchctl load "$plist_file" || {
    print_error "Failed to load launchd service"
    return 1
  }

  print_success "launchd service installed: ${service_name}"
  return 0
}

# Uninstall launchd service
# Arguments:
#   $1 - Service name
# Returns:
#   0 on success, 1 on failure
uninstall_launchd_service() {
  local service_name="$1"

  print_info "Uninstalling launchd service: ${service_name}"

  local plist_file="$HOME/Library/LaunchAgents/${service_name}.plist"

  if [[ ! -f "$plist_file" ]]; then
    print_warning "Service not installed: ${service_name}"
    return 0
  fi

  # Unload the service
  launchctl unload "$plist_file" 2>/dev/null || true

  # Remove the plist file
  rm -f "$plist_file"

  print_success "launchd service uninstalled: ${service_name}"
  return 0
}

# ============================================================================
# SERVICE INSTALLATION (Linux - systemd)
# ============================================================================

# Install systemd service for Linux
# Arguments:
#   $1 - Service name (e.g., clawfarm-gateway)
#   $2 - Service file path (template)
#   $3 - Deploy directory
#   $4 - Log directory
# Returns:
#   0 on success, 1 on failure
install_systemd_service() {
  local service_name="$1"
  local service_template="$2"
  local deploy_dir="$3"
  local log_dir="$4"

  print_info "Installing systemd service: ${service_name}"

  # Check if running as root (required for systemd)
  if [[ $EUID -ne 0 ]]; then
    if ! sudo -n true 2>/dev/null; then
      print_error "systemd service installation requires root privileges"
      echo "  Please run with sudo" >&2
      return 1
    fi
  fi

  local systemd_dir="/etc/systemd/system"
  local service_file="${systemd_dir}/${service_name}.service"

  # Generate service file with substituted variables
  sed -e "s|\${DEPLOY_DIR}|${deploy_dir}|g" \
      -e "s|\${LOG_DIR}|${log_dir}|g" \
      -e "s|\${USER}|${USER}|g" \
      "$service_template" | sudo tee "$service_file" > /dev/null

  # Reload systemd
  sudo systemctl daemon-reload || {
    print_error "Failed to reload systemd"
    return 1
  }

  # Enable the service (start on boot)
  sudo systemctl enable "$service_name" || {
    print_error "Failed to enable service"
    return 1
  }

  # Start the service
  sudo systemctl start "$service_name" || {
    print_error "Failed to start service"
    return 1
  }

  print_success "systemd service installed: ${service_name}"
  return 0
}

# Uninstall systemd service
# Arguments:
#   $1 - Service name
# Returns:
#   0 on success, 1 on failure
uninstall_systemd_service() {
  local service_name="$1"

  print_info "Uninstalling systemd service: ${service_name}"

  local service_file="/etc/systemd/system/${service_name}.service"

  if [[ ! -f "$service_file" ]]; then
    print_warning "Service not installed: ${service_name}"
    return 0
  fi

  # Stop and disable the service
  sudo systemctl stop "$service_name" 2>/dev/null || true
  sudo systemctl disable "$service_name" 2>/dev/null || true

  # Remove the service file
  sudo rm -f "$service_file"

  # Reload systemd
  sudo systemctl daemon-reload

  print_success "systemd service uninstalled: ${service_name}"
  return 0
}

# ============================================================================
# PLATFORM-SPECIFIC SERVICE INSTALLATION
# ============================================================================

# Install OpenClaw gateway auto-start service
# Arguments:
#   $1 - Deploy directory
#   $2 - Log directory
#   $3 - Auto-start flag (true/false)
# Returns:
#   0 on success, 1 on failure
install_gateway_service() {
  local deploy_dir="$1"
  local log_dir="$2"
  local auto_start="${3:-true}"

  if [[ "$auto_start" != "true" ]]; then
    print_info "Auto-start disabled, skipping service installation"
    return 0
  fi

  print_info "Installing OpenClaw gateway auto-start service..."

  if [[ "$OSTYPE" == darwin* ]]; then
    # macOS - use launchd
    local script_dir
    script_dir="$(cd "${SCRIPT_DIR}/.." && pwd)"
    local plist_template="${script_dir}/services/macos/com.clawfarm.gateway.plist"

    if [[ ! -f "$plist_template" ]]; then
      print_error "Service template not found: ${plist_template}"
      return 1
    fi

    install_launchd_service "com.clawfarm.gateway" "$plist_template" "$deploy_dir" "$log_dir"
  elif [[ "$OSTYPE" == linux* ]]; then
    # Linux - use systemd
    local script_dir
    script_dir="$(cd "${SCRIPT_DIR}/.." && pwd)"
    local service_template="${script_dir}/services/linux/clawfarm-gateway.service"

    if [[ ! -f "$service_template" ]]; then
      print_error "Service template not found: ${service_template}"
      return 1
    fi

    install_systemd_service "clawfarm-gateway" "$service_template" "$deploy_dir" "$log_dir"
  else
    print_warning "Auto-start not supported on this platform"
    return 0
  fi
}

# Uninstall OpenClaw gateway auto-start service
# Returns:
#   0 on success, 1 on failure
uninstall_gateway_service() {
  print_info "Uninstalling OpenClaw gateway auto-start service..."

  if [[ "$OSTYPE" == darwin* ]]; then
    uninstall_launchd_service "com.clawfarm.gateway"
  elif [[ "$OSTYPE" == linux* ]]; then
    uninstall_systemd_service "clawfarm-gateway"
  else
    print_warning "Service uninstallation not supported on this platform"
    return 0
  fi
}

# Install Docker auto-start helper
# Returns:
#   0 on success, 1 on failure
install_docker_autostart() {
  print_info "Setting up Docker auto-start..."

  if [[ "$OSTYPE" == darwin* ]]; then
    # macOS - install launchd helper to start Docker Desktop on login
    local script_dir
    script_dir="$(cd "${SCRIPT_DIR}/.." && pwd)"
    local plist_template="${script_dir}/services/macos/com.docker.docker.plist.helper"

    if [[ ! -f "$plist_template" ]]; then
      print_warning "Docker auto-start template not found"
      return 0
    fi

    local home_dir="$HOME"
    install_launchd_service "com.docker.docker.user" "$plist_template" "$home_dir" "$home_dir/Library/Logs"
  elif [[ "$OSTYPE" == linux* ]]; then
    # Linux - enable Docker systemd service
    if command -v systemctl &> /dev/null; then
      print_info "Enabling Docker systemd service..."

      if [[ $EUID -ne 0 ]]; then
        sudo systemctl enable docker 2>/dev/null || {
          print_warning "Could not enable Docker auto-start (requires sudo)"
          return 0
        }
      else
        systemctl enable docker || {
          print_warning "Could not enable Docker auto-start"
          return 0
        }
      fi

      print_success "Docker auto-start enabled"
    fi
  else
    print_warning "Docker auto-setup not supported on this platform"
  fi

  return 0
}

# ============================================================================
# UTILITY FUNCTIONS
# ============================================================================

# Check if service is installed
# Arguments:
#   $1 - Service name
# Returns:
#   0 if installed, 1 if not
is_service_installed() {
  local service_name="$1"

  if [[ "$OSTYPE" == darwin* ]]; then
    launchctl list | grep -q "$service_name"
  elif [[ "$OSTYPE" == linux* ]]; then
    systemctl list-unit-files | grep -q "${service_name}.service"
  else
    return 1
  fi
}

# Get service status
# Arguments:
#   $1 - Service name
# Returns:
#   Service status string
get_service_status() {
  local service_name="$1"

  if [[ "$OSTYPE" == darwin* ]]; then
    if launchctl list | grep -q "$service_name"; then
      echo "running"
    else
      echo "not running"
    fi
  elif [[ "$OSTYPE" == linux* ]]; then
    systemctl is-active "$service_name" 2>/dev/null || echo "unknown"
  else
    echo "unsupported"
  fi
}

# Print info message
print_info() {
  echo -e "${BLUE}ℹ${NC} $1"
}

# Print success message
print_success() {
  echo -e "${GREEN}✓${NC} $1"
}

# Export functions
export -f install_launchd_service
export -f uninstall_launchd_service
export -f install_systemd_service
export -f uninstall_systemd_service
export -f install_gateway_service
export -f uninstall_gateway_service
export -f install_docker_autostart
export -f is_service_installed
export -f get_service_status
