# platform-detection.sh - Platform and architecture detection for deployment scripts
# Part of ClawFarm Deployment Tools Phase 0


# Global variable to store detected platform
PLATFORM=""

# Detect the current platform (Linux, macOS, or WSL2)
# Sets the global PLATFORM variable and outputs it
# Returns:
#   0 always (detection always succeeds)
detect_platform() {
  if [[ "$OSTYPE" == "linux-gnu"* ]]; then
    # Check if we're in WSL2
    if [[ -f /proc/version ]] && grep -qi "microsoft" /proc/version 2>/dev/null; then
      export PLATFORM="wsl2"
    else
      export PLATFORM="linux"
    fi
  elif [[ "$OSTYPE" == "darwin"* ]]; then
    export PLATFORM="macos"
  elif [[ "$OSTYPE" == "cygwin" ]] || [[ "$OSTYPE" == "msys" ]]; then
    export PLATFORM="windows"
  else
    export PLATFORM="unknown"
  fi

  echo "$PLATFORM"
  return 0
}

# Check if current platform is macOS
# Returns:
#   0 if on macOS, 1 otherwise
is_macos() {
  if [[ -z "$PLATFORM" ]]; then
    detect_platform > /dev/null
  fi
  [[ "$PLATFORM" == "macos" ]]
}

# Check if current platform is Linux (not WSL2)
# Returns:
#   0 if on Linux, 1 otherwise
is_linux() {
  if [[ -z "$PLATFORM" ]]; then
    detect_platform > /dev/null
  fi
  [[ "$PLATFORM" == "linux" ]]
}

# Check if current platform is WSL2
# Returns:
#   0 if on WSL2, 1 otherwise
is_wsl2() {
  if [[ -z "$PLATFORM" ]]; then
    detect_platform > /dev/null
  fi
  [[ "$PLATFORM" == "wsl2" ]]
}

# Check if current platform is Windows
# Returns:
#   0 if on Windows, 1 otherwise
is_windows() {
  if [[ -z "$PLATFORM" ]]; then
    detect_platform > /dev/null
  fi
  [[ "$PLATFORM" == "windows" ]]
}

# Get the system architecture
# Normalizes architecture names to common formats
# Returns:
#   Architecture string (amd64, arm64, etc.)
get_architecture() {
  local arch
  arch="$(uname -m)"

  case "$arch" in
    x86_64|x64|amd64)
      echo "amd64"
      ;;
    aarch64|arm64)
      echo "arm64"
      ;;
    i386|i686)
      echo "386"
      ;;
    *)
      echo "$arch"
      ;;
  esac
}

# Get the number of CPU cores
# Returns:
#   Number of CPU cores
get_cpu_count() {
  local cores

  if is_macos; then
    cores="$(sysctl -n hw.ncpu)"
  elif is_linux || is_wsl2; then
    cores="$(nproc 2>/dev/null || echo 1)"
  else
    cores="1"
  fi

  echo "$cores"
}

# Get the total system memory in MB
# Returns:
#   Total memory in MB
get_memory_mb() {
  local mem_mb

  if is_macos; then
    # macOS uses different sysctl names
    mem_mb="$(sysctl -n hw.memsize)"
    mem_mb=$((mem_mb / 1024 / 1024))
  elif is_linux || is_wsl2; then
    # Linux: read from /proc/meminfo
    mem_mb="$(grep MemTotal /proc/meminfo | awk '{print $2}')"
    mem_mb=$((mem_mb / 1024))
  else
    mem_mb="0"
  fi

  echo "$mem_mb"
}

# Check if running with elevated privileges (sudo/root)
# Returns:
#   0 if elevated, 1 otherwise
is_elevated() {
  if [[ "$EUID" -eq 0 ]]; then
    return 0
  fi

  # Check for sudo on Linux/macOS
  if command -v sudo &> /dev/null; then
    if sudo -n true 2>/dev/null; then
      return 0
    fi
  fi

  return 1
}

# Get the default shell for the current user
# Returns:
#   Path to the default shell
get_default_shell() {
  if is_macos || is_linux || is_wsl2; then
    echo "$SHELL"
  else
    echo "/bin/sh"
  fi
}

# Check if a command is available in PATH
# This is a convenience wrapper around 'command -v'
# Arguments:
#   $1 - Command to check
# Returns:
#   0 if command exists, 1 otherwise
command_exists() {
  command -v "$1" &> /dev/null
}

# Export functions for use in subshells
export -f detect_platform
export -f is_macos
export -f is_linux
export -f is_wsl2
export -f is_windows
export -f get_architecture
export -f get_cpu_count
export -f get_memory_mb
export -f is_elevated
export -f get_default_shell
export -f command_exists
