#!/usr/bin/env bash
# install.sh - Main installation script for ClawFarm
# Part of ClawFarm Deployment Tools Phase 6: Main Installation Script


# ============================================================================
# SCRIPT CONFIGURATION
# ============================================================================

# Script directory and project root

# Source library dependencies
# shellcheck source=scripts/deploy/lib/validation.sh
# shellcheck source=scripts/deploy/lib/config.sh
# shellcheck source=scripts/deploy/lib/state.sh
# shellcheck source=scripts/deploy/lib/deployment.sh
# shellcheck source=scripts/deploy/lib/platform-detection.sh
# shellcheck source=scripts/deploy/lib/services.sh

# Installation configuration
INSTALL_VERSION="${INSTALL_VERSION:-1.0.0}"
DEPLOY_DIR="${DEPLOY_DIR:-/opt/openclaw}"
STATE_DIR="${STATE_DIR:-/var/lib/openclaw}"
STATE_FILE="${STATE_FILE:-${STATE_DIR}/deployment/state.json}"
LOG_FILE="${LOG_FILE:-/var/log/openclaw/install.log}"
LOG_LEVEL="${LOG_LEVEL:-INFO}"

# Installation steps (in order)
declare -a INSTALL_STEPS=(
    "validate_platform"
    "validate_environment"
    "gather_configuration"
    "validate_token"
    "initialize_state"
    "generate_configuration"
    "pull_images"
    "start_containers"
    "verify_deployment"
    "setup_channels"
    "setup_skills"
    "setup_autostart"
    "save_checkpoint"
)

# Total number of steps (for progress display)
TOTAL_STEPS=${#INSTALL_STEPS[@]}

# ============================================================================
# COLORS AND OUTPUT
# ============================================================================

# Extended colors for progress
if [ -t 1 ]; then
    BLUE='\033[0;34m'
    CYAN='\033[0;36m'
    MAGENTA='\033[0;35m'
    BOLD='\033[1m'
    NC='\033[0m'
else
    BLUE=''
    CYAN=''
    MAGENTA=''
    BOLD=''
    NC=''
fi

# Print info message (blue)
print_info() {
    echo -e "${BLUE}ℹ${NC} $1"
}

# Print step header with progress
print_step() {
    local step_num="$1"
    local step_desc="$2"
    local progress=$((step_num * 100 / TOTAL_STEPS))

    echo ""
    echo -e "${CYAN}${BOLD}[${step_num}/${TOTAL_STEPS}]${NC} ${step_desc}"
    echo -e "${BLUE}Progress: ${progress}%${NC}"
}

# ============================================================================
# LOGGING
# ============================================================================

# Log message with timestamp
# Arguments:
#   $1 - Log level (DEBUG, INFO, WARN, ERROR)
#   $2 - Message to log
log_message() {
    local log_level="$1"
    local message="$2"
    local timestamp
    timestamp="$(date -u +'%Y-%m-%dT%H:%M:%SZ')"

    # Check if we should log this level
    case "${LOG_LEVEL:-INFO}" in
        DEBUG)
            ;;
        INFO)
            [[ "$log_level" == "DEBUG" ]] && return 0
            ;;
        WARN)
            [[ "$log_level" =~ ^(DEBUG|INFO)$ ]] && return 0
            ;;
        ERROR)
            [[ "$log_level" =~ ^(DEBUG|INFO|WARN)$ ]] && return 0
            ;;
    esac

    # Ensure log directory exists (suppress errors for early calls before directory setup)
    local log_dir
    log_dir="$(dirname "$LOG_FILE")"
    if [[ ! -d "$log_dir" ]]; then
        mkdir -p "$log_dir" 2>/dev/null || {
            # Fallback to /tmp if home directory creation fails
            if [[ "$LOG_FILE" =~ ^$HOME ]] && [[ "$OSTYPE" == darwin* ]]; then
                LOG_FILE="/tmp/openclaw-install-$(date +%s).log"
                log_dir="/tmp"
                mkdir -p "$log_dir" 2>/dev/null || true
            fi
        }
    fi

    # Write to log file (silently fail if directory doesn't exist yet)
    if [[ -d "$log_dir" ]]; then
        echo "[${timestamp}] [${log_level}] ${message}" >> "$LOG_FILE" 2>/dev/null || true
    fi

    # Also print to stdout/stderr for non-DEBUG
    if [[ "$log_level" != "DEBUG" ]] || [[ "${VERBOSE:-false}" == "true" ]]; then
        case "$log_level" in
            ERROR)
                print_error "$message"
                ;;
            WARN)
                print_warning "$message"
                ;;
            INFO)
                print_info "$message"
                ;;
            DEBUG)
                echo -e "${BLUE}[DEBUG]${NC} $message"
                ;;
        esac
    fi
}

# ============================================================================
# USAGE AND HELP
# ============================================================================

# Show usage information
usage() {
    cat <<EOF
${BOLD}ClawFarm Installation Script${NC} v${INSTALL_VERSION}

${BOLD}USAGE:${NC}
    $(basename "$0") [OPTIONS]

${BOLD}OPTIONS:${NC}
    -c, --config FILE          Load configuration from file
    -t, --type TYPE             Deployment type: local|cloud (default: interactive)
    -r, --resource-token TOKEN  Control Plane registration token
    -a, --agency-id ID          Agency ID (default: auto-generate)
    -n, --resource-name NAME    Resource/gateway name (default: hostname)
    -l, --llm-key KEY           LLM API key for agent intelligence
    -m, --llm-model MODEL       Default LLM model (default: qwen/qwen-2.5-plus)
    -p, --install-path PATH     Installation directory (default: ~/openclaw-gateway for local)
    -v, --verbose               Enable verbose output
    -d, --dry-run               Show what would be done without executing
    --enable-autostart          Enable auto-start services (default)
    --disable-autostart         Disable auto-start services
    --resume                    Resume from checkpoint
    -y, --yes                   Auto-confirm all prompts (non-interactive)
    -h, --help                  Show this help message

${BOLD}ENVIRONMENT VARIABLES:${NC}
    LOG_LEVEL                  Logging level: DEBUG, INFO, WARN, ERROR (default: INFO)
    DEPLOY_DIR                 Installation directory (default: ~/openclaw-gateway for local, /opt/openclaw for cloud)
    STATE_DIR                  State directory (default: <deploy_dir>/.state)
    LOG_FILE                   Log file path (default: <deploy_dir>/logs/install.log)
    CONTROL_PLANE_API_URL      Control Plane API URL
    REGISTRY                   Container registry URL (for cloud deployments)
    IMAGE_TAG                  Image tag to deploy (default: latest)

${BOLD}DEPLOYMENT TYPES:${NC}
    local                      Deploy locally using Docker
    cloud                      Deploy using cloud container registry

${BOLD}EXAMPLES:${NC}
    # Interactive mode (default)
    $(basename "$0")

    # Non-interactive with config file
    $(basename "$0") --config /path/to/config.json --yes

    # Local deployment with explicit settings
    $(basename "$0") --type local --resource-token abc123

    # Local deployment with LLM key (for agent intelligence)
    $(basename "$0") --type local --resource-token abc123 --llm-key sk-or-xyz789

    # Local deployment without auto-start
    $(basename "$0") --type local --resource-token abc123 --disable-autostart

    # Cloud deployment with custom registry
    $(basename "$0") --type cloud --registry myregistry.azurecr.io

    # Verbose output for debugging
    $(basename "$0") --verbose

    # Dry run to see what would happen
    $(basename "$0") --dry-run

    # Resume from checkpoint after failure
    $(basename "$0") --resume

${BOLD}EXIT CODES:${NC}
    0    Installation successful
    1    Installation failed
    2    Validation error
    3    User cancelled
    4    Resume failed (no checkpoint found)

${BOLD}FOR MORE INFORMATION:${NC}
    https://docs.clawfarm.ca/installation

EOF
    exit 0
}

# ============================================================================
# ARGUMENT PARSING
# ============================================================================

# Default values
CONFIG_FILE=""
DEPLOYMENT_TYPE=""
RESOURCE_TOKEN=""
AGENCY_ID=""
RESOURCE_NAME=""
LLM_KEY=""
DEFAULT_LLM_MODEL="moonshotai/kimi-k2.5"
VERBOSE=false
DRY_RUN=false
RESUME=false
AUTO_CONFIRM=false
SKIP_TOKEN_VALIDATION=false

# Parse command line arguments
parse_arguments() {
    while [[ $# -gt 0 ]]; do
        case $1 in
            -c|--config)
                CONFIG_FILE="$2"
                shift 2
                ;;
            -t|--type)
                DEPLOYMENT_TYPE="$2"
                if [[ ! "$DEPLOYMENT_TYPE" =~ ^(local|cloud)$ ]]; then
                    print_error "Invalid deployment type: $DEPLOYMENT_TYPE"
                    echo "  Must be one of: local, cloud" >&2
                    exit 2
                fi
                shift 2
                ;;
            -r|--resource-token)
                RESOURCE_TOKEN="$2"
                shift 2
                ;;
            -a|--agency-id)
                AGENCY_ID="$2"
                shift 2
                ;;
            -n|--resource-name)
                RESOURCE_NAME="$2"
                shift 2
                ;;
            -l|--llm-key)
                LLM_KEY="$2"
                shift 2
                ;;
            -m|--llm-model)
                DEFAULT_LLM_MODEL="$2"
                shift 2
                ;;
            -p|--install-path)
                DEPLOY_DIR="$2"
                # Mark that deploy dir was set manually so we don't override it
                DEPLOY_DIR_SET_MANUALLY=true
                shift 2
                ;;
            -v|--verbose)
                VERBOSE=true
                export LOG_LEVEL="DEBUG"
                shift
                ;;
            -d|--dry-run)
                DRY_RUN=true
                log_message "INFO" "Dry run mode: no changes will be made"
                shift
                ;;
            --enable-autostart)
                ENABLE_AUTOSTART=true
                shift
                ;;
            --disable-autostart)
                ENABLE_AUTOSTART=false
                shift
                ;;
            --resume)
                RESUME=true
                shift
                ;;
            -y|--yes)
                AUTO_CONFIRM=true
                shift
                ;;
            -h|--help)
                usage
                ;;
            --skip-token-validation)
                SKIP_TOKEN_VALIDATION=true
                shift
                ;;
            *)
                print_error "Unknown option: $1"
                echo "  Use --help for usage information" >&2
                exit 2
                ;;
        esac
    done
}

# ============================================================================
# PLATFORM-SPECIFIC CONFIGURATION
# ============================================================================

# Set platform-appropriate deployment directories
# This should be called after argument parsing when DEPLOYMENT_TYPE is known
set_platform_directories() {
    # For macOS local deployments, use home directory (unless manually set)
    if [[ "$DEPLOYMENT_TYPE" == "local" ]] && [[ "$OSTYPE" == darwin* ]]; then
        if [[ -z "${DEPLOY_DIR_SET_MANUALLY:-}" ]]; then
            log_message "INFO" "Using home directory for macOS local deployment"
            # Only set if not already customized by user
            if [[ "$DEPLOY_DIR" == "/opt/openclaw" ]]; then
                DEPLOY_DIR="$HOME/openclaw-gateway"
            fi
        fi
        # Keep state and logs in the deploy directory for cleaner setup
        if [[ "$STATE_DIR" == "/var/lib/openclaw" ]]; then
            STATE_DIR="${DEPLOY_DIR}/.state"
        fi
        if [[ "$LOG_FILE" == "/var/log/openclaw/install.log" ]]; then
            LOG_FILE="${DEPLOY_DIR}/logs/install.log"
        fi
    fi

    # Update STATE_FILE to use new STATE_DIR
    STATE_FILE="${STATE_DIR}/deployment/state.json"

    # Export for use in subshells
    export DEPLOY_DIR STATE_DIR STATE_FILE LOG_FILE

    log_message "DEBUG" "Deployment directory: $DEPLOY_DIR"
    log_message "DEBUG" "State directory: $STATE_DIR"
    log_message "DEBUG" "Log file: $LOG_FILE"
}

# ============================================================================
# INTERACTIVE PROMPTS
# ============================================================================

# Prompt for deployment type
prompt_deployment_type() {
    if [[ -n "$DEPLOYMENT_TYPE" ]]; then
        return 0
    fi

    echo ""
    echo "Select deployment type:"
    echo "  1) local  - Deploy locally using Docker"
    echo "  2) cloud  - Deploy using cloud container registry"
    echo ""

    if [[ "$AUTO_CONFIRM" == "true" ]]; then
        DEPLOYMENT_TYPE="local"
        log_message "INFO" "Using default deployment type: local"
        return 0
    fi

    local choice
    read -rp "Deployment type [1-2, default: 1]: " choice
    choice="${choice:-1}"

    case "$choice" in
        1|local)
            DEPLOYMENT_TYPE="local"
            ;;
        2|cloud)
            DEPLOYMENT_TYPE="cloud"
            ;;
        *)
            print_error "Invalid choice. Using default: local"
            DEPLOYMENT_TYPE="local"
            ;;
    esac

    log_message "INFO" "Deployment type: $DEPLOYMENT_TYPE"
}

# Prompt for resource token
prompt_resource_token() {
    if [[ -n "$RESOURCE_TOKEN" ]]; then
        return 0
    fi

    echo ""
    if [[ "$AUTO_CONFIRM" == "true" ]]; then
        print_error "Resource token is required in non-interactive mode"
        echo "  Use --resource-token or --config to provide it" >&2
        exit 2
    fi

    while [[ -z "$RESOURCE_TOKEN" ]]; do
        read -rp "Enter Control Plane registration token: " RESOURCE_TOKEN
        if [[ -z "$RESOURCE_TOKEN" ]]; then
            print_error "Resource token is required"
        fi
    done

    log_message "DEBUG" "Resource token provided (length: ${#RESOURCE_TOKEN})"
}

# Validate resource token with control plane
validate_resource_token() {
    local token="$1"
    local control_plane_url="${CONTROL_PLANE_API_URL:-https://api.clawfarm.ca}"

    print_info "Validating resource token with control plane..."
    log_message "INFO" "Token validation starting"

    # Use the registration endpoint which requires resource token
    local registration_url="${control_plane_url}/api/resources/register"

    # Create validation registration payload using correct format
    local validation_gateway_id="install-validation-$(date +%s)"
    local validation_gateway_name="install-validation-$(date +%s)"

    local registration_data
    registration_data=$(cat <<EOF
{
  "name": "${validation_gateway_name}",
  "gateway_id": "${validation_gateway_id}",
  "deployment_type": "docker",
  "ip_address": "validation",
  "region": "auto",
  "version": "1.0.0",
  "capabilities": ["llm", "channels", "skills"]
}
EOF
)

    local response
    local http_code

    response=$(curl -s -w "\n%{http_code}" -X POST \
        -H "Content-Type: application/json" \
        -H "X-Resource-Token: ${token}" \
        -d "$registration_data" \
        "${registration_url}" 2>/dev/null)

    http_code=$(echo "$response" | tail -n1)
    response_body=$(echo "$response" | head -n-1)

    log_message "DEBUG" "Token validation HTTP code: ${http_code}"
    log_message "DEBUG" "Token validation response: ${response_body}"

    if [[ "$http_code" == "200" ]] || [[ "$http_code" == "201" ]]; then
        print_success "Resource token validated successfully"
        log_message "INFO" "Token validation passed - registration accepted"
        return 0
    elif [[ "$http_code" == "401" ]]; then
        print_error "Invalid resource token - authentication failed"
        log_message "ERROR" "Token validation failed: 401 Unauthorized"
        return 1
    elif [[ "$http_code" == "403" ]]; then
        print_error "Resource token not accepted - access denied"
        log_message "ERROR" "Token validation failed: 403 Forbidden"
        return 1
    elif [[ "$http_code" == "404" ]]; then
        print_warning "Control plane endpoint not found - assuming token is valid"
        log_message "WARN" "Registration endpoint not found, continuing with installation"
        return 0
    else
        print_error "Unable to validate token (HTTP ${http_code}) - installation cannot continue"
        log_message "ERROR" "Token validation failed with HTTP ${http_code}"
        echo ""
        echo "Possible reasons:"
        echo "  - Control plane API is not accessible"
        echo "  - Network connectivity problems"
        echo "  - Invalid control plane URL: ${control_plane_url}"
        echo ""
        echo "To skip token validation, use: --skip-token-validation"
        return 1
    fi
}

# Prompt for agency ID
prompt_agency_id() {
    if [[ -n "$AGENCY_ID" ]]; then
        return 0
    fi

    # Auto-generate by default
    AGENCY_ID="$(generate_uuid)"
    log_message "INFO" "Generated agency ID: $AGENCY_ID"

    if [[ "$AUTO_CONFIRM" == "true" ]]; then
        return 0
    fi

    echo ""
    read -rp "Agency ID [${AGENCY_ID}]: " input
    if [[ -n "$input" ]]; then
        AGENCY_ID="$input"
    fi

    log_message "INFO" "Agency ID: $AGENCY_ID"
}

# Prompt for resource name
prompt_resource_name() {
    if [[ -n "$RESOURCE_NAME" ]]; then
        return 0
    fi

    # Default to <username>-<hostname> format as documented
    local hostname_part
    hostname_part="$(hostname -s 2>/dev/null || echo gateway)"
    local default_name="${USER}-${hostname_part}"
    RESOURCE_NAME="$default_name"

    log_message "INFO" "Resource name: $RESOURCE_NAME"

    if [[ "$AUTO_CONFIRM" == "true" ]]; then
        return 0
    fi

    echo ""
    read -rp "Resource name [${RESOURCE_NAME}]: " input
    if [[ -n "$input" ]]; then
        RESOURCE_NAME="$input"
    fi

    log_message "INFO" "Resource name: $RESOURCE_NAME"
}

# Prompt for gateway port
prompt_gateway_port() {
    if [[ -n "${GATEWAY_PORT:-}" ]]; then
        return 0
    fi

    export GATEWAY_PORT="${GATEWAY_PORT:-18789}"

    if [[ "$AUTO_CONFIRM" == "true" ]]; then
        return 0
    fi

    echo ""
    read -rp "Gateway port [${GATEWAY_PORT}]: " input
    if [[ -n "$input" ]]; then
        if validate_port "$input" 2>/dev/null; then
            export GATEWAY_PORT="$input"
        else
            print_warning "Invalid port, using default: ${GATEWAY_PORT}"
        fi
    fi

    log_message "INFO" "Gateway port: $GATEWAY_PORT"
}

# Prompt for LLM key
prompt_llm_key() {
    if [[ -n "$LLM_KEY" ]]; then
        return 0
    fi

    echo ""
    if [[ "$AUTO_CONFIRM" == "true" ]]; then
        print_warning "No LLM key provided - agent features will be limited"
        log_message "WARN" "LLM key not provided in non-interactive mode"
        LLM_KEY=""
        return 0
    fi

    echo ""
    echo "LLM API Key (for agent intelligence)"
    echo "  Leave empty to configure manually later"
    echo "  Get a free key at: https://openrouter.ai/keys"
    echo ""
    read -rp "LLM API Key [optional]: " LLM_KEY

    if [[ -n "$LLM_KEY" ]]; then
        log_message "INFO" "LLM key provided (length: ${#LLM_KEY})"
    else
        log_message "INFO" "LLM key not provided - can be configured later"
    fi
}

# Prompt for LLM model
prompt_llm_model() {
    if [[ "$AUTO_CONFIRM" == "true" ]]; then
        log_message "INFO" "Using default LLM model: $DEFAULT_LLM_MODEL"
        return 0
    fi

    echo ""
    echo "Default LLM Model (for agent intelligence)"
    echo "  Available models include:"
    echo "    - qwen/qwen-2.5-plus (recommended, free tier)"
    echo "    - google/gemma-3-27b-it"
    echo "    - meta-llama/llama-3.1-8b-instruct"
    echo "    - mistralai/mistral-7b-instruct"
    echo "  See https://openrouter.ai/models for more options"
    echo ""
    read -rp "Default LLM Model [default: qwen/qwen-2.5-plus]: " input_model

    if [[ -n "$input_model" ]]; then
        DEFAULT_LLM_MODEL="$input_model"
    fi

    log_message "INFO" "LLM model set to: $DEFAULT_LLM_MODEL"
}

# Confirm installation
confirm_installation() {
    if [[ "$AUTO_CONFIRM" == "true" ]]; then
        return 0
    fi

    echo ""
    echo -e "${BOLD}=== Installation Summary ===${NC}"
    echo "  Deployment Type:  $DEPLOYMENT_TYPE"
    echo "  Resource Name:    $RESOURCE_NAME"
    echo "  Agency ID:        $AGENCY_ID"
    echo "  LLM Key:          ${LLM_KEY:+Configured}${LLM_KEY:-Not configured}"
    echo "  LLM Model:        $DEFAULT_LLM_MODEL"
    echo "  Gateway Port:     ${GATEWAY_PORT:-18789}"
    echo "  Install Directory: $DEPLOY_DIR"
    echo "  State Directory:   $STATE_DIR"
    echo ""

    local confirm
    read -rp "Proceed with installation? [y/N]: " confirm
    case "$confirm" in
        [Yy]|[Yy][Ee][Ss])
            log_message "INFO" "Installation confirmed by user"
            return 0
            ;;
        *)
            log_message "INFO" "Installation cancelled by user"
            echo "Installation cancelled."
            exit 3
            ;;
    esac
}

# ============================================================================
# INSTALLATION STEPS
# ============================================================================

# Helper function to create directory with error handling
# Arguments:
#   $1 - Directory path to create
#   $2 - Optional: Description for error messages
# Returns:
#   0 on success, 1 on failure
ensure_directory_exists() {
    local dir_path="$1"
    local description="${2:-Directory}"

    if [[ -d "$dir_path" ]]; then
        return 0
    fi

    log_message "INFO" "Creating ${description}: ${dir_path}"

    if ! mkdir -p "$dir_path" 2>/dev/null; then
        log_message "ERROR" "Failed to create ${description}: ${dir_path}"
        echo "  Check permissions and try again" >&2
        return 1
    fi

    return 0
}

# ============================================================================
# INSTALLATION STEPS
# ============================================================================

# Step 1: Validate platform
step_validate_platform() {
    print_step 1 "Validating platform"
    log_message "INFO" "Platform detection starting"

    # Detect platform
    if ! detect_platform; then
        log_message "ERROR" "Failed to detect platform"
        return 1
    fi

    local platform
    platform="${PLATFORM:-$(detect_platform)}"
    local arch
    arch="$(get_architecture)"

    log_message "INFO" "Detected platform: ${platform} (${arch})"

    # Check platform compatibility
    case "$platform" in
        ubuntu|macos|wsl2|debian)
            log_message "INFO" "Platform ${platform} is supported"
            ;;
        *)
            log_message "WARN" "Platform ${platform} may not be fully supported"
            ;;
    esac

    print_success "Platform validation passed: ${platform} ${arch}"
    return 0
}

# Step 2: Validate environment
step_validate_environment() {
    print_step 2 "Validating environment"
    log_message "INFO" "Environment validation starting"

    # Check Docker
    if ! check_docker; then
        log_message "ERROR" "Docker validation failed"
        return 1
    fi

    # Check Docker Compose
    if ! check_docker_compose; then
        log_message "ERROR" "Docker Compose validation failed"
        return 1
    fi

    # Check prerequisites
    if ! validate_prerequisites; then
        log_message "ERROR" "Prerequisites validation failed"
        return 1
    fi

    # Check disk space (using home directory, not $DEPLOY_DIR which may not exist yet)
    local check_path="${HOME:-.}"
    if ! check_disk_space 5 "$check_path"; then
        log_message "ERROR" "Insufficient disk space"
        return 1
    fi

    # Check memory
    check_memory 2048 || log_message "WARN" "Low memory detected"

    print_success "Environment validation passed"
    return 0
}

# Step 3: Gather configuration
step_gather_configuration() {
    print_step 3 "Gathering configuration"
    log_message "INFO" "Configuration gathering starting"

    # Load config file if provided
    if [[ -n "$CONFIG_FILE" ]]; then
        log_message "INFO" "Loading configuration from: $CONFIG_FILE"
        if ! load_config_file "$CONFIG_FILE"; then
            log_message "ERROR" "Failed to load configuration file"
            return 1
        fi
    fi

    # Prompt for missing values
    prompt_deployment_type
    prompt_resource_token
    prompt_agency_id
    prompt_resource_name
    prompt_llm_key
    prompt_llm_model
    prompt_gateway_port

    # Export configuration for templates
    export CONTROL_PLANE_API_URL="${CONTROL_PLANE_API_URL:-https://api.clawfarm.ca/v1}"
    export RESOURCE_TOKEN="$RESOURCE_TOKEN"
    export GATEWAY_NAME="$RESOURCE_NAME"
    export GATEWAY_ID="$AGENCY_ID"
    export DEPLOYMENT_TYPE="$DEPLOYMENT_TYPE"
    export LLM_KEY="$LLM_KEY"
    export DEFAULT_LLM_MODEL="$DEFAULT_LLM_MODEL"

    log_message "INFO" "Configuration gathered successfully"
    print_success "Configuration complete"
    return 0
}

# Step 3.5: Validate resource token
step_validate_token() {
    print_step 4 "Validating resource token"
    log_message "INFO" "Resource token validation starting"

    if [[ "$DRY_RUN" == "true" ]]; then
        log_message "INFO" "DRY RUN: Would validate resource token with control plane"
        print_success "Token validated (dry run)"
        return 0
    fi

    # Skip validation if explicitly disabled
    if [[ "$SKIP_TOKEN_VALIDATION" == "true" ]]; then
        print_warning "Token validation skipped (SKIP_TOKEN_VALIDATION=true)"
        log_message "WARN" "Token validation skipped by user request"
        return 0
    fi

    # Validate the resource token with control plane
    if ! validate_resource_token "$RESOURCE_TOKEN"; then
        log_message "ERROR" "Resource token validation failed"
        print_error "Installation cannot continue without a valid resource token"
        echo ""
        echo "Please check:"
        echo "  1. Your resource token is correct"
        echo "  2. The token has not expired or been revoked"
        echo "  3. You have network connectivity to the control plane"
        echo "  4. The control plane API is accessible"
        echo ""
        echo "To get a new resource token, visit: https://clawfarm.ca/dashboard"
        return 1
    fi

    # Update state
    set_current_step "$STATE_FILE" "token_validated"
    add_completed_step "$STATE_FILE" "validate_token"

    print_success "Token validation complete"
    return 0
}

# Step 5: Initialize state
step_initialize_state() {
    print_step 5 "Initializing deployment state"
    log_message "INFO" "State initialization starting"

    if [[ "$DRY_RUN" == "true" ]]; then
        log_message "INFO" "DRY RUN: Would initialize state at $STATE_FILE"
        print_success "State initialized (dry run)"
        return 0
    fi

    # Create state directory with helper function
    if ! ensure_directory_exists "$STATE_DIR" "state directory"; then
        return 1
    fi

    # Initialize state file
    if ! init_state "$STATE_FILE" "$DEPLOYMENT_TYPE"; then
        # Check if we're resuming
        if [[ "$RESUME" == "true" ]]; then
            log_message "INFO" "State file exists, loading for resume"
            if ! verify_state_integrity "$STATE_FILE"; then
                log_message "ERROR" "State file integrity check failed"
                return 1
            fi
        else
            log_message "ERROR" "Failed to initialize state"
            return 1
        fi
    fi

    # Set initial checkpoint
    add_checkpoint "$STATE_FILE" "init" "{\"deployment_type\":\"$DEPLOYMENT_TYPE\"}"

    print_success "State initialized"
    return 0
}

# Step 6: Generate configuration files
step_generate_configuration() {
    print_step 6 "Generating configuration files"
    log_message "INFO" "Configuration file generation starting"

    if [[ "$DRY_RUN" == "true" ]]; then
        log_message "INFO" "DRY RUN: Would generate config files in $DEPLOY_DIR"
        print_success "Configuration files generated (dry run)"
        return 0
    fi

    # Create deploy directory with helper function
    if ! ensure_directory_exists "$DEPLOY_DIR" "deploy directory"; then
        return 1
    fi

    # Create workspace subdirectory
    local workspace_dir="${DEPLOY_DIR}/workspace"
    if ! ensure_directory_exists "$workspace_dir" "workspace directory"; then
        return 1
    fi

    # Auto-detect image tag if not specified
    if [[ -z "${IMAGE_TAG:-}" ]]; then
        log_message "INFO" "Auto-detecting latest image version..."
        IMAGE_TAG=$(get_latest_image_tag "${REGISTRY:-}")
        export IMAGE_TAG
        log_message "INFO" "Auto-detected image version: ${IMAGE_TAG}"
    fi

    # Set IMAGE_TAG_SEPARATOR for template rendering
    export IMAGE_TAG_SEPARATOR=":"

    # Generate .env file with all necessary configuration
    if ! generate_env_file "$DEPLOY_DIR" "$RESOURCE_TOKEN" \
        "$RESOURCE_NAME" "$AGENCY_ID" "${CONTROL_PLANE_API_URL:-}" "$LLM_KEY" \
        "${REGISTRY:-}" "${IMAGE_TAG:-}" "${GATEWAY_PORT:-18789}"; then
        log_message "ERROR" "Failed to generate .env file"
        return 1
    fi

    # Generate docker-compose.yml (now uses .env file for variables)
    if ! generate_compose_file "$DEPLOY_DIR" \
        "${REGISTRY:-}" "${IMAGE_TAG:-}" "${GATEWAY_PORT:-18789}"; then
        log_message "ERROR" "Failed to generate docker-compose.yml"
        return 1
    fi

    # Generate openclaw.json
    if ! generate_openclaw_config "$workspace_dir" "${CONTROL_PLANE_API_URL:-}"; then
        log_message "ERROR" "Failed to generate openclaw.json"
        return 1
    fi

    # Generate OpenClaw gateway state configuration
    # This creates the .openclaw directory with proper port configuration and default LLM model
    if ! generate_openclaw_state_config "$DEPLOY_DIR" "${GATEWAY_PORT:-18789}" "${DEFAULT_LLM_MODEL:-qwen/qwen-2.5-plus}"; then
        log_message "ERROR" "Failed to generate OpenClaw state configuration"
        return 1
    fi

    # Update state
    set_current_step "$STATE_FILE" "configuration_generated"
    add_completed_step "$STATE_FILE" "generate_configuration"

    print_success "Configuration files generated"
    return 0
}

# Step 7: Pull images
step_pull_images() {
    print_step 7 "Pulling Docker images"
    log_message "INFO" "Image pull starting"

    if [[ "$DRY_RUN" == "true" ]]; then
        log_message "INFO" "DRY RUN: Would pull images for $DEPLOYMENT_TYPE deployment"
        print_success "Images pulled (dry run)"
        return 0
    fi

    if ! pull_images "$DEPLOY_DIR" "${REGISTRY:-}" "${IMAGE_TAG:-latest}"; then
        log_message "ERROR" "Failed to pull images"
        return 1
    fi

    # Update state
    set_current_step "$STATE_FILE" "images_pulled"
    add_completed_step "$STATE_FILE" "pull_images"

    print_success "Images pulled successfully"
    return 0
}

# Step 8: Start containers
step_start_containers() {
    print_step 8 "Starting containers"
    log_message "INFO" "Container startup starting"

    if [[ "$DRY_RUN" == "true" ]]; then
        log_message "INFO" "DRY RUN: Would start containers with docker-compose"
        print_success "Containers started (dry run)"
        return 0
    fi

    if ! start_containers "$DEPLOY_DIR"; then
        log_message "ERROR" "Failed to start containers"
        return 1
    fi

    # Update state
    set_current_step "$STATE_FILE" "containers_started"
    add_completed_step "$STATE_FILE" "start_containers"

    print_success "Containers started"
    return 0
}

# Step 9: Verify deployment
step_verify_deployment() {
    print_step 9 "Verifying deployment"
    log_message "INFO" "Deployment verification starting"

    if [[ "$DRY_RUN" == "true" ]]; then
        log_message "INFO" "DRY RUN: Would verify deployment health"
        print_success "Deployment verified (dry run)"
        return 0
    fi

    # Wait for health check
    local max_attempts=30
    local attempt=0

    while [[ $attempt -lt $max_attempts ]]; do
        if curl -f -s "http://localhost:${GATEWAY_PORT:-18789}/health" &>/dev/null; then
            log_message "INFO" "Health check passed"
            break
        fi

        attempt=$((attempt + 1))
        echo -n "."
        sleep 2
    done
    echo ""

    if [[ $attempt -eq $max_attempts ]]; then
        log_message "ERROR" "Health check failed - service not responding"
        return 1
    fi

    # Verify Control Plane registration
    # (This would be implemented with actual registration check)

    # Update state
    set_current_step "$STATE_FILE" "deployment_verified"
    add_completed_step "$STATE_FILE" "verify_deployment"

    print_success "Deployment verified successfully"
    return 0
}

# Step 10: Setup communication channels
step_setup_channels() {
    print_step 10 "Setting up communication channels"
    log_message "INFO" "Channel setup starting"

    if [[ "$DRY_RUN" == "true" ]]; then
        log_message "INFO" "DRY RUN: Would setup communication channels"
        print_success "Communication channels configured (dry run)"
        return 0
    fi

    # Find the gateway container
    local gateway_container=""
    local env_file="${DEPLOY_DIR}/.env"

    if [[ -f "$env_file" ]]; then
        # Extract resource token and get last 4 characters
        local resource_token
        resource_token=$(grep "^RESOURCE_TOKEN=" "$env_file" | cut -d'=' -f2)
        if [[ -n "$resource_token" ]]; then
            local token_suffix="${resource_token: -4}"
            gateway_container="clawfarm-gateway-${token_suffix}"
        fi
    fi

    # Fallback to pattern matching if exact match fails
    if [[ -z "$gateway_container" ]] || ! docker ps --format '{{.Names}}' | grep -q "^${gateway_container}$"; then
        gateway_container=$(docker ps --format '{{.Names}}' | grep -E '^clawfarm-gateway-' | head -1)
    fi

    if [[ -z "$gateway_container" ]]; then
        log_message "WARN" "Gateway container not found for channel setup"
        print_warning "Channel setup skipped - gateway container not found"
        print_info "You can setup channels manually after installation"
        return 0
    fi

    log_message "INFO" "Using gateway container: $gateway_container"

    # Check if gateway is running
    if ! docker exec "$gateway_container" pwd &>/dev/null; then
        log_message "WARN" "Gateway container is not running"
        print_warning "Channel setup skipped - gateway not running"
        print_info "You can setup channels manually after starting the gateway"
        return 0
    fi

    # Install WeChat plugin
    log_message "INFO" "Installing WeChat plugin..."
    print_info "Installing WeChat communication plugin"

    if docker exec "$gateway_container" openclaw plugins install "@tencent-weixin/openclaw-weixin" 2>&1 | grep -q "Installed plugin"; then
        log_message "INFO" "WeChat plugin installed successfully"

        # Add to plugins.allow list (exclude built-in browser plugin - we use agent-browser skill instead)
        docker exec "$gateway_container" openclaw config set plugins.allow '["openclaw-weixin","memory-core","openrouter","qwen"]' --json 2>/dev/null || true

        log_message "INFO" "WeChat plugin configured"
        print_success "WeChat plugin installed"
    else
        log_message "WARN" "Failed to install WeChat plugin"
        print_warning "WeChat plugin installation failed"
    fi

    # Update state
    set_current_step "$STATE_FILE" "channels_configured"
    add_completed_step "$STATE_FILE" "setup_channels"

    print_success "Communication channels configured"
    echo ""
    echo "WeChat Plugin Installation:"
    echo "  Status:        Installed"
    echo "  Next Step:     Login to WeChat channel"
    echo ""
    echo "To complete WeChat setup:"
    echo "  docker exec $gateway_container openclaw channels login --channel openclaw-weixin"
    echo ""
    echo "Then scan the QR code with WeChat to connect."
    echo ""

    return 0
}

# Step 11: Setup built-in skills
step_setup_skills() {
    print_step 11 "Setting up built-in skills"
    log_message "INFO" "Skills setup starting"

    if [[ "$DRY_RUN" == "true" ]]; then
        log_message "INFO" "DRY RUN: Would setup built-in skills"
        print_success "Built-in skills configured (dry run)"
        return 0
    fi

    # Find the gateway container
    local gateway_container=""
    local env_file="${DEPLOY_DIR}/.env"

    if [[ -f "$env_file" ]]; then
        # Extract resource token and get last 4 characters
        local resource_token
        resource_token=$(grep "^RESOURCE_TOKEN=" "$env_file" | cut -d'=' -f2)
        if [[ -n "$resource_token" ]]; then
            local token_suffix="${resource_token: -4}"
            gateway_container="clawfarm-gateway-${token_suffix}"
        fi
    fi

    # Fallback to pattern matching if exact match fails
    if [[ -z "$gateway_container" ]] || ! docker ps --format '{{.Names}}' | grep -q "^${gateway_container}$"; then
        gateway_container=$(docker ps --format '{{.Names}}' | grep -E '^clawfarm-gateway-' | head -1)
    fi

    if [[ -z "$gateway_container" ]]; then
        log_message "WARN" "Gateway container not found for skills setup"
        print_warning "Skills setup skipped - gateway container not found"
        print_info "You can setup skills manually after installation"
        return 0
    fi

    log_message "INFO" "Using gateway container: $gateway_container"

    # Check if gateway is running
    if ! docker exec "$gateway_container" pwd &>/dev/null; then
        log_message "WARN" "Gateway container is not running"
        print_warning "Skills setup skipped - gateway not running"
        print_info "You can setup skills manually after starting the gateway"
        return 0
    fi

    # Copy all built-in skills from /usr/local/share/openclaw/skills to workspace
    log_message "INFO" "Copying all built-in skills to workspace..."
    print_info "Copying built-in skills to workspace"

    # Create workspace skills directory if it doesn't exist
    docker exec "$gateway_container" mkdir -p /workspace/skills/ 2>/dev/null

    # Copy all skills from built-in location to workspace
    local skills_copied=0
    local skills_failed=0

    # List all directories in the skills source directory
    local skills_list
    skills_list=$(docker exec "$gateway_container" find /usr/local/share/openclaw/skills -mindepth 1 -maxdepth 1 -type d -printf "%f\n" 2>/dev/null)

    if [[ -n "$skills_list" ]]; then
        while IFS= read -r skill_dir; do
            if [[ -n "$skill_dir" ]]; then
                local skill_name="$skill_dir"
                log_message "INFO" "Copying skill: $skill_name"

                if docker exec "$gateway_container" cp -r "/usr/local/share/openclaw/skills/${skill_name}" "/workspace/skills/" 2>/dev/null; then
                    log_message "INFO" "Skill '$skill_name' copied successfully"
                    skills_copied=$((skills_copied + 1))

                    # Check if this skill has an agent-browser CLI
                    if [[ "$skill_name" == "Agent-Browser-CLI" ]]; then
                        if docker exec "$gateway_container" command -v agent-browser &>/dev/null; then
                            local agent_browser_version
                            agent_browser_version=$(docker exec "$gateway_container" agent-browser --version 2>/dev/null || echo "unknown")
                            log_message "INFO" "agent-browser CLI version: $agent_browser_version"
                        fi
                    fi
                else
                    log_message "WARN" "Failed to copy skill: $skill_name"
                    skills_failed=$((skills_failed + 1))
                fi
            fi
        done <<< "$skills_list"
    else
        log_message "WARN" "No skills found in /usr/local/share/openclaw/skills"
        print_warning "No built-in skills found to copy"
    fi

    # Report results
    if [[ $skills_copied -gt 0 ]]; then
        log_message "INFO" "Successfully copied $skills_copied skill(s)"
        print_success "Copied $skills_copied built-in skill(s) to workspace"
    fi

    if [[ $skills_failed -gt 0 ]]; then
        log_message "WARN" "Failed to copy $skills_failed skill(s)"
        print_warning "Failed to copy $skills_failed skill(s)"
    fi

    # Update state
    set_current_step "$STATE_FILE" "skills_configured"
    add_completed_step "$STATE_FILE" "setup_skills"

    print_success "Built-in skills configured"
    echo ""
    echo "Skills Overview:"
    echo "  Total Copied:  $skills_copied skill(s)"
    echo "  Location:       /workspace/skills/"
    echo ""

    # Show individual skills if any were copied
    if [[ $skills_copied -gt 0 ]]; then
        echo "Available Skills:"
        docker exec "$gateway_container" find /workspace/skills -mindepth 1 -maxdepth 1 -type d -printf "  - %f\n" 2>/dev/null | sort
        echo ""
    fi

    # Show agent-browser specific info if available
    if [[ -n "$agent_browser_version" ]]; then
        echo "Agent-Browser-CLI:"
        echo "  CLI Version:   $agent_browser_version"
        echo "  CDP Proxy:     clawfarm-browser-proxy:9223"
        echo "  Status:        Ready for browser automation"
        echo ""
    fi

    echo "Built-in browser plugin is disabled - agent-browser skill is preferred."
    echo "Agents can now use the installed skills for various automation tasks."
    echo ""

    return 0
}

# Step 12: Setup auto-start services
step_setup_autostart() {
    print_step 12 "Setting up auto-start services"
    log_message "INFO" "Auto-start service setup starting"

    if [[ "$DRY_RUN" == "true" ]]; then
        log_message "INFO" "DRY RUN: Would setup auto-start services"
        print_success "Auto-start services configured (dry run)"
        return 0
    fi

    # Check if auto-start is enabled
    local enable_autostart="${ENABLE_AUTOSTART:-true}"

    if [[ "$enable_autostart" != "true" ]]; then
        log_message "INFO" "Auto-start disabled by user"
        print_success "Auto-start skipped (disabled)"
        return 0
    fi

    # Setup log directory for services
    local log_dir
    if [[ "$OSTYPE" == darwin* ]] && [[ "$DEPLOYMENT_TYPE" == "local" ]]; then
        log_dir="$HOME/openclaw-gateway/logs"
    else
        log_dir="/var/log/openclaw"
    fi

    if ! ensure_directory_exists "$log_dir" "log directory"; then
        log_message "WARN" "Could not create log directory, auto-start may not work properly"
    fi

    # Install Docker auto-start helper
    if ! install_docker_autostart; then
        log_message "WARN" "Failed to setup Docker auto-start"
    fi

    # Install OpenClaw gateway service
    if ! install_gateway_service "$DEPLOY_DIR" "$log_dir" "$enable_autostart"; then
        log_message "ERROR" "Failed to install gateway auto-start service"
        print_warning "Auto-start setup failed, but deployment is complete"
        print_warning "You can manually start the gateway with: cd $DEPLOY_DIR && docker compose up -d"
        return 0  # Don't fail the entire installation
    fi

    # Update state
    set_current_step "$STATE_FILE" "autostart_configured"
    add_completed_step "$STATE_FILE" "setup_autostart"

    print_success "Auto-start services configured"
    echo ""
    echo "✓ Gateway will start automatically on system boot"
    echo "✓ Docker Desktop will start automatically on login (macOS)"
    echo ""
    echo "To manage services:"
    if [[ "$OSTYPE" == darwin* ]]; then
        echo "  macOS: launchctl list | grep clawfarm"
        echo "  Stop:  launchctl unload ~/Library/LaunchAgents/com.clawfarm.gateway.plist"
        echo "  Start: launchctl load ~/Library/LaunchAgents/com.clawfarm.gateway.plist"
    else
        echo "  Linux: systemctl status clawfarm-gateway"
        echo "  Stop:  sudo systemctl stop clawfarm-gateway"
        echo "  Start: sudo systemctl start clawfarm-gateway"
    fi

    return 0
}

# Step 13: Save checkpoint
step_save_checkpoint() {
    print_step 13 "Saving deployment checkpoint"
    log_message "INFO" "Checkpoint save starting"

    if [[ "$DRY_RUN" == "true" ]]; then
        log_message "INFO" "DRY RUN: Would save checkpoint"
        print_success "Checkpoint saved (dry run)"
        return 0
    fi

    # Save final checkpoint
    add_checkpoint "$STATE_FILE" "complete" "{\"status\":\"completed\",\"agency_id\":\"$AGENCY_ID\"}"

    # Update status to completed
    update_status "$STATE_FILE" "completed"

    print_success "Installation complete!"
    return 0
}

# ============================================================================
# RESUME FUNCTIONALITY
# ============================================================================

# Resume installation from checkpoint
resume_installation() {
    log_message "INFO" "Resuming installation from checkpoint"

    # Load state
    local state_json
    if ! state_json="$(load_state "$STATE_FILE")"; then
        log_message "ERROR" "Failed to load state for resume"
        exit 4
    fi

    # Get checkpoint info
    local checkpoint_step
    checkpoint_step="$(echo "$state_json" | jq -r '.checkpoint.step')"

    if [[ -z "$checkpoint_step" ]] || [[ "$checkpoint_step" == "null" ]]; then
        log_message "ERROR" "No checkpoint found in state file"
        exit 4
    fi

    # Get completed steps
    local completed_steps
    completed_steps="$(echo "$state_json" | jq -r '.completed_steps[]')"

    echo ""
    print_info "Resuming from checkpoint: ${checkpoint_step}"
    print_info "Completed steps: $(echo "$completed_steps" | tr '\n' ',' | sed 's/,$//')"

    # Find which step to resume from
    local resume_from=0
    for step in "${INSTALL_STEPS[@]}"; do
        if ! echo "$completed_steps" | grep -q "^${step}$"; then
            break
        fi
        resume_from=$((resume_from + 1))
    done

    # Run remaining steps
    run_installation_steps "$resume_from"
}

# ============================================================================
# MAIN INSTALLATION ORCHESTRATION
# ============================================================================

# Run installation steps
# Arguments:
#   $1 - Starting step index (default: 0)
run_installation_steps() {
    local start_step="${1:-0}"
    local current_step=$start_step
    local step_index=0

    for step in "${INSTALL_STEPS[@]}"; do
        # Skip steps before start point
        if [[ $step_index -lt $start_step ]]; then
            step_index=$((step_index + 1))
            continue
        fi

        current_step=$((step_index + 1))

        # Run step function
        local step_function="step_${step}"
        if declare -f "$step_function" > /dev/null; then
            if ! $step_function; then
                log_message "ERROR" "Step ${step} failed"
                update_status "$STATE_FILE" "failed" 2>/dev/null || true

                echo ""
                print_error "Installation failed at step: ${step}"
                echo "  Check logs at: $LOG_FILE"
                echo "  Resume with: $(basename "$0") --resume"

                return 1
            fi
        else
            log_message "WARN" "Step function not found: ${step_function}, skipping"
        fi

        # Save checkpoint after each step
        if [[ "$DRY_RUN" != "true" ]]; then
            add_checkpoint "$STATE_FILE" "$step" "{\"step_index\":$step_index}" 2>/dev/null || true
        fi

        step_index=$((step_index + 1))
    done

    return 0
}

# Main installation function
main() {
    local install_start_time
    install_start_time=$(date +%s)

    # Print header
    echo ""
    echo -e "${BOLD}${BLUE}╔═══════════════════════════════════════╗${NC}"
    echo -e "${BOLD}${BLUE}║  ClawFarm Installation Script v${INSTALL_VERSION}      ║${NC}"
    echo -e "${BOLD}${BLUE}╚═══════════════════════════════════════╝${NC}"
    echo ""

    # Log start
    log_message "INFO" "Installation starting"
    log_message "INFO" "Arguments: $*"

    # Parse command line arguments
    parse_arguments "$@"

    # Set platform-appropriate directories (must be after parse_arguments)
    set_platform_directories

    # Handle resume
    if [[ "$RESUME" == "true" ]]; then
        resume_installation
        local exit_code=$?
    else
        # Run interactive prompts if not auto-confirm
        if [[ "$AUTO_CONFIRM" != "true" ]]; then
            confirm_installation
        fi

        # Run installation steps
        run_installation_steps 0
        local exit_code=$?
    fi

    # Calculate duration
    local install_end_time
    install_end_time=$(date +%s)
    local install_duration=$((install_end_time - install_start_time))

    # Print summary
    echo ""
    if [[ $exit_code -eq 0 ]]; then
        echo -e "${GREEN}${BOLD}✓ Installation completed successfully!${NC}"
    else
        echo -e "${YELLOW}${BOLD}⚠ Installation completed with errors${NC}"
    fi
    echo ""
    echo "Resource Name:    $RESOURCE_NAME"
    echo "Agency ID:        $AGENCY_ID"
    echo "Gateway Port:     ${GATEWAY_PORT:-18789}"
    echo "Install Directory: $DEPLOY_DIR"
    echo "Duration:         ${install_duration}s"
    echo ""

    # Extract and display gateway token if available (even if installation failed)
    local openclaw_config="${DEPLOY_DIR}/.openclaw/openclaw.json"
    if [[ -f "$openclaw_config" ]]; then
        local gateway_token
        gateway_token=$(grep -o '"token":[[:space:]]*"[^"]*"' "$openclaw_config" | cut -d'"' -f4 2>/dev/null)
        if [[ -n "$gateway_token" ]]; then
            echo -e "${BOLD}Gateway Authentication:${NC}"
            echo "Token:            $gateway_token"
            echo "Config Path:      $openclaw_config"
            echo ""
            echo "Quick command to get token:"
            echo "  cat $openclaw_config | jq -r '.gateway.auth.token'"
            echo ""
        fi
    fi

    # Show next steps only if installation succeeded
    if [[ $exit_code -eq 0 ]]; then
        echo "To start the gateway:"
        echo "  cd $DEPLOY_DIR"
        echo "  docker compose up -d"
        echo ""
        echo "To view logs:"
        echo "  docker compose logs -f"
        echo ""
        echo "Browser Automation:"
        echo "  - Built-in browser plugin: DISABLED"
        echo "  - Agent-Browser-CLI skill: ENABLED"
        echo "  - Browser Proxy: clawfarm-browser-proxy:9223"
        echo "  - Usage: agent-browser --cdp http://clawfarm-browser-proxy:9223 <command>"
        echo ""
        echo "Installation logs: $LOG_FILE"
    else
        echo -e "${RED}${BOLD}✗ Installation failed${NC}"
        echo ""
        echo "Check logs at: $LOG_FILE"
        echo "Resume with: $(basename "$0") --resume"
    fi

    return $exit_code
}

# Run main function only if script is executed directly (not sourced)
if [[ "${BASH_SOURCE[0]}" == "${0}" ]]; then
    main "$@"
fi

